/// <summary>
/// Editor tool that builds the "Fishing Village at Sunset" scene from scratch:
/// sculpted and painted coastal terrain, sea, pier, boats, wooden houses, lighthouse,
/// fishing props, sunset lighting, fog and post-processing, plus the explorer camera and viewpoints.
/// Every mesh, texture and material is generated by this script (no imported asset packs).
/// Menu: Tools > Fishing Village > Build World.
/// </summary>
public static class VillageBuilder
{
