    [MenuItem("Tools/Fishing Village/Build World")]
    public static void BuildAll()
    {
        litShader = Shader.Find("Universal Render Pipeline/Lit");
        if (litShader == null) { Debug.LogError("URP Lit shader not found"); return; }

        CleanGenerated();
        MakeFolders();
        mainPath = SamplePath(MainPathPoints);
        trails = SamplePath(LighthouseTrailPoints);
        trails.AddRange(SamplePath(CoveTrailPoints));

        var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

        MakeMaterials();
        var p = MakePrefabs();

        var terrainGroup = new GameObject("Terrain");
        terrain = BuildTerrain(terrainGroup.transform, p);
        BuildWater();

        var lighting = BuildLighting();
        BuildBuildings(p);
        BuildLighthouse(p);
        BuildHarbour(p);
        BuildVillageProps(p);
        BuildCove(p);
        BuildHilltop(p);
        BuildNature(p);
        BuildEffects(p);
        BuildPlayerAndViewpoints();
        lighting.transform.SetSiblingIndex(1);

        EditorSceneManager.SaveScene(scene, ScenePath);
        EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(ScenePath, true) };
        BakeEnvironmentLighting();
        EditorSceneManager.SaveScene(scene, ScenePath);
        AssetDatabase.SaveAssets();
        Debug.Log("Fishing Village world built.");
    }

    static void CleanGenerated()
    {
        string[] generated = { "Assets/Materials", "Assets/Textures", "Assets/Meshes", "Assets/Prefabs", "Assets/Terrain", "Assets/Scenes", "Assets/Settings/PP_FishingVillage.asset", "Assets/Settings/LS_FishingVillage.lighting" };
        EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        foreach (var g in generated) AssetDatabase.DeleteAsset(g);
        AssetDatabase.Refresh();
    }

    static void MakeFolders()
    {
        string[] folders =
        {
            "Assets/Scenes", "Assets/Scripts", "Assets/Materials", "Assets/Materials/Buildings", "Assets/Materials/Boats",
            "Assets/Materials/Props", "Assets/Materials/Nature", "Assets/Materials/Water", "Assets/Materials/Effects", "Assets/Materials/Sky",
            "Assets/Textures", "Assets/Textures/Terrain", "Assets/Textures/Surfaces", "Assets/Textures/Effects",
            "Assets/Meshes", "Assets/Meshes/Buildings", "Assets/Meshes/Boats", "Assets/Meshes/Props", "Assets/Meshes/Nature",
            "Assets/Prefabs", "Assets/Prefabs/Buildings", "Assets/Prefabs/Boats", "Assets/Prefabs/Props", "Assets/Prefabs/Nature",
            "Assets/Terrain", "Assets/ThirdParty"
        };
        foreach (var f in folders)
        {
            if (AssetDatabase.IsValidFolder(f)) continue;
            string parent = Path.GetDirectoryName(f).Replace('\\', '/');
            AssetDatabase.CreateFolder(parent, Path.GetFileName(f));
        }
    }

    // =====================================================================
    // Maths helpers
    // =====================================================================
    static float SS(float a, float b, float x)
    {
        float t = Mathf.Clamp01((x - a) / (b - a));
        return t * t * (3f - 2f * t);
    }

    static float Fbm(float x, float z, int octaves)
    {
        float sum = 0f, amp = 1f, norm = 0f, freq = 1f;
        for (int i = 0; i < octaves; i++)
        {
            sum += Mathf.PerlinNoise(x * freq + 31.7f, z * freq + 71.3f) * amp;
            norm += amp; amp *= 0.5f; freq *= 2f;
        }
        return sum / norm;
    }

    static float Gauss(float x, float c, float w) { float t = (x - c) / w; return Mathf.Exp(-t * t); }

    static List<Vector2> SamplePath(Vector2[] pts)
    {
        var result = new List<Vector2>();
        for (int i = 0; i < pts.Length - 1; i++)
        {
            Vector2 p0 = pts[Mathf.Max(i - 1, 0)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Mathf.Min(i + 2, pts.Length - 1)];
            int steps = Mathf.CeilToInt(Vector2.Distance(p1, p2) / 0.75f);
            for (int s = 0; s < steps; s++)
            {
                float t = s / (float)steps, t2 = t * t, t3 = t2 * t;
                result.Add(0.5f * ((2f * p1) + (-p0 + p2) * t + (2f * p0 - 5f * p1 + 4f * p2 - p3) * t2 + (-p0 + 3f * p1 - 3f * p2 + p3) * t3));
            }
        }
        result.Add(pts[pts.Length - 1]);
        return result;
    }

    static float DistToSamples(List<Vector2> samples, float x, float z, float cutoff)
    {
        float best = cutoff * cutoff;
        for (int i = 0; i < samples.Count; i++)
        {
            float dx = samples[i].x - x, dz = samples[i].y - z;
            float d = dx * dx + dz * dz;
            if (d < best) best = d;
        }
        return Mathf.Sqrt(best);
    }

    static float MainPathDist(float x, float z) { return DistToSamples(mainPath, x, z, 30f); }
    static float TrailDist(float x, float z) { return DistToSamples(trails, x, z, 30f); }

    // =====================================================================
    // Coastline and height
    // =====================================================================
    // z of the shoreline for a given x: a bay in the middle, a high headland to the east (lighthouse) and a lower one to the west.
    static float ShoreZ(float x)
    {
        return 168f - 30f * Gauss(x, 150f, 50f) + 75f * Gauss(x, 262f, 28f) + 40f * Gauss(x, 25f, 25f)
               + (Mathf.PerlinNoise(x * 0.045f, 3.3f) - 0.5f) * 8f;
    }

    static float BaseHeight(float x, float z)
    {
        float d = ShoreZ(x) - z; // > 0 on land
        float h;
        if (d >= 0f)
        {
            h = 9.6f + SS(0f, 12f, d) * 2.4f + SS(4f, 115f, d) * 38f;
            h += (Fbm(x * 0.02f, z * 0.02f, 4) - 0.5f) * 10f * SS(10f, 80f, d);

            // Raised headlands with cliffs dropping into the sea
            float e = 1f - SS(20f, 40f, Vector2.Distance(new Vector2(x, z), EastHeadland));
            h = Mathf.Lerp(h, Mathf.Max(h, 32f + (Fbm(x * 0.08f, z * 0.08f, 2) - 0.5f) * 2f), e * SS(0f, 7f, d));
            float w = 1f - SS(16f, 34f, Vector2.Distance(new Vector2(x, z), WestHeadland));
            h = Mathf.Lerp(h, Mathf.Max(h, 22f + (Fbm(x * 0.08f + 9f, z * 0.08f, 2) - 0.5f) * 3f), w * SS(0f, 6f, d));
        }
        else
        {
            h = 9.6f - SS(0f, 40f, -d) * 8.5f + (Fbm(x * 0.05f, z * 0.05f, 2) - 0.5f) * 1.2f;
        }

        // Mountains closing the south edge, ridges on the east and west land edges
        float ridge = Fbm(x * 0.025f + 50f, z * 0.025f + 20f, 4);
        h += SS(62f, 4f, z) * (28f + ridge * 40f);
        float landMask = SS(-12f, 24f, d);
        h += SS(42f, 4f, x) * (22f + ridge * 26f) * landMask;
        h += SS(278f, 316f, x) * (22f + ridge * 26f) * landMask * (1f - SS(170f, 215f, z));
        return h;
    }

    static float[] padHeights;
    static float startHeight, squareHeight;

    static float FinalHeight(float x, float z)
    {
        float h = BaseHeight(x, z);
        Vector2 p = new Vector2(x, z);

        for (int i = 0; i < Sites.Length; i++)
        {
            float ds = Vector2.Distance(p, Sites[i].p);
            if (ds < Sites[i].r + 7f) h = Mathf.Lerp(h, padHeights[i], 1f - SS(Sites[i].r, Sites[i].r + 7f, ds));
        }
        float dq = Vector2.Distance(p, Square);
        h = Mathf.Lerp(h, squareHeight, 1f - SS(9f, 17f, dq));
        float dl = Vector2.Distance(p, LighthousePos);
        h = Mathf.Lerp(h, lighthouseGround, 1f - SS(5f, 11f, dl));

        h -= (1f - SS(1.2f, 3.2f, MainPathDist(x, z))) * 0.25f;
        h -= (1f - SS(0.8f, 2.4f, TrailDist(x, z))) * 0.18f;
        return h;
    }

    // =====================================================================
    // Textures
    // =====================================================================
    static float TileNoise(float x, float y, float period, float seed)
    {
        float a = Mathf.PerlinNoise(x + seed, y + seed);
        float b = Mathf.PerlinNoise(x - period + seed, y + seed);
        float c = Mathf.PerlinNoise(x + seed, y - period + seed);
        float d = Mathf.PerlinNoise(x - period + seed, y - period + seed);
        float u = x / period, v = y / period;
        return Mathf.Lerp(Mathf.Lerp(a, b, u), Mathf.Lerp(c, d, u), v);
    }

    static float TileFbm(float u, float v, float basePeriod, float seed, int octaves)
    {
        float sum = 0f, amp = 1f, norm = 0f, p = basePeriod;
        for (int o = 0; o < octaves; o++)
        {
            sum += TileNoise(u * p, v * p, p, seed + o * 37f) * amp;
            norm += amp; amp *= 0.5f; p *= 2f;
        }
        return sum / norm;
    }

    static float Hash(int i, int seed)
    {
        uint h = (uint)(i * 374761393 + seed * 668265263);
        h = (h ^ (h >> 13)) * 1274126177u;
        return (h & 0xFFFF) / 65535f;
    }

    delegate Color PixelFunc(float u, float v, System.Random rng);

    static Texture2D MakeTexture(string path, int size, PixelFunc func, bool alpha, bool repeat, bool normalMap = false)
    {
        var tex = new Texture2D(size, size, TextureFormat.RGBA32, false);
        var rng = new System.Random(path.GetHashCode());
        var px = new Color[size * size];
        for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
                px[y * size + x] = func(x / (float)size, y / (float)size, rng);
        tex.SetPixels(px);
        tex.Apply();
        File.WriteAllBytes(path, tex.EncodeToPNG());
        Object.DestroyImmediate(tex);
        AssetDatabase.ImportAsset(path);
        var imp = (TextureImporter)AssetImporter.GetAtPath(path);
        imp.wrapMode = repeat ? TextureWrapMode.Repeat : TextureWrapMode.Clamp;
        imp.alphaIsTransparency = alpha;
        imp.mipmapEnabled = true;
        if (normalMap) imp.textureType = TextureImporterType.NormalMap;
        imp.SaveAndReimport();
        return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    }

    static Texture2D GrassTexture()
    {
        return MakeTexture("Assets/Textures/Terrain/T_CoastalGrass.png", 256, (u, v, r) =>
        {
            float n = TileFbm(u, v, 4f, 500f, 4);
            float n2 = TileFbm(u, v, 2f, 900f, 3);
            Color c = Color.Lerp(new Color(0.26f, 0.34f, 0.12f), new Color(0.46f, 0.50f, 0.19f), n);
            c = Color.Lerp(c, new Color(0.62f, 0.56f, 0.28f), SS(0.5f, 0.75f, n2) * 0.55f); // dry golden patches
            c *= 0.9f + 0.2f * TileFbm(u, v, 32f, 700f, 1);
            c.a = 1f; return c;
        }, false, true);
    }

    static Texture2D SandTexture()
    {
        return MakeTexture("Assets/Textures/Terrain/T_Sand.png", 256, (u, v, r) =>
        {
            float n = TileFbm(u, v, 3f, 1300f, 3);
            float grain = (float)r.NextDouble();
            float ripple = Mathf.Sin((v + TileFbm(u, v, 2f, 1500f, 2) * 0.3f) * Mathf.PI * 2f * 12f) * 0.5f + 0.5f;
            Color c = Color.Lerp(new Color(0.74f, 0.63f, 0.46f), new Color(0.88f, 0.78f, 0.60f), n);
            c *= 0.93f + 0.07f * ripple + (grain - 0.5f) * 0.08f;
            c.a = 1f; return c;
        }, false, true);
    }

    static Texture2D WetSandTexture()
    {
        return MakeTexture("Assets/Textures/Terrain/T_WetSand_Pebbles.png", 256, (u, v, r) =>
        {
            float n = TileFbm(u, v, 4f, 1700f, 3);
            float pebble = TileFbm(u, v, 18f, 2500f, 2);
            Color c = Color.Lerp(new Color(0.30f, 0.26f, 0.21f), new Color(0.46f, 0.39f, 0.30f), n);
            if (pebble > 0.62f) c = Color.Lerp(c, new Color(0.52f, 0.50f, 0.48f), SS(0.62f, 0.7f, pebble));
            c.a = 1f; return c;
        }, false, true);
    }

    static Texture2D DirtTexture()
    {
        return MakeTexture("Assets/Textures/Terrain/T_DirtPath.png", 256, (u, v, r) =>
        {
            float n = TileFbm(u, v, 4f, 2100f, 4);
            float pebble = TileFbm(u, v, 16f, 2500f, 2);
            Color c = Color.Lerp(new Color(0.36f, 0.27f, 0.18f), new Color(0.54f, 0.42f, 0.29f), n);
            if (pebble > 0.66f) c = Color.Lerp(c, new Color(0.58f, 0.55f, 0.50f), SS(0.66f, 0.72f, pebble));
            c.a = 1f; return c;
        }, false, true);
    }

    static Texture2D RockTexture()
    {
        return MakeTexture("Assets/Textures/Terrain/T_CliffRock.png", 256, (u, v, r) =>
        {
            float n = TileFbm(u, v, 3f, 3100f, 5);
            float ridged = 1f - Mathf.Abs(2f * TileFbm(u, v, 6f, 3900f, 3) - 1f);
            float strata = Mathf.Sin((v + n * 0.15f) * Mathf.PI * 2f * 7f) * 0.5f + 0.5f;
            Color c = Color.Lerp(new Color(0.30f, 0.27f, 0.25f), new Color(0.56f, 0.52f, 0.47f), n) * (0.7f + 0.3f * ridged);
            c *= 0.88f + 0.12f * strata;
            c.a = 1f; return c;
        }, false, true);
    }

    // Light grey horizontal boards; materials tint them with their base colour.
    static Texture2D PlankTexture()
    {
        const int boards = 8;
        return MakeTexture("Assets/Textures/Surfaces/T_WoodPlanks.png", 256, (u, v, r) =>
        {
            int b = Mathf.FloorToInt(v * boards);
            float inBoard = v * boards - b;
            float shade = 0.82f + Hash(b, 11) * 0.18f;
            float grain = TileFbm(u, v * 0.25f, 6f, 4100f + b * 3f, 3);
            float streak = Mathf.Sin((u * 40f + grain * 6f) * Mathf.PI) * 0.5f + 0.5f;
            float c = shade * (0.86f + 0.1f * grain + 0.05f * streak);
            if (inBoard < 0.07f) c *= 0.45f;            // gap between boards
            else if (inBoard > 0.9f) c *= 0.9f;         // shadow under the board above
            float seamU = Hash(b, 23);
            if (Mathf.Abs(u - seamU) < 0.006f) c *= 0.5f; // butt joint
            return new Color(c, c, c, 1f);
        }, false, true);
    }

    static Texture2D ShingleTexture()
    {
        const int rows = 10, cols = 8;
        return MakeTexture("Assets/Textures/Surfaces/T_RoofShingles.png", 256, (u, v, r) =>
        {
            int row = Mathf.FloorToInt(v * rows);
            float inRow = v * rows - row;
            float uu = u * cols + (row % 2) * 0.5f;
            int col = Mathf.FloorToInt(uu);
            float inCol = uu - col;
            float shade = 0.75f + Hash(col + row * 31, 5) * 0.25f;
            float c = shade * (0.6f + 0.4f * inRow);        // lower edge of each row is darker
            if (inCol < 0.05f) c *= 0.45f;
            c *= 0.9f + 0.1f * TileFbm(u, v, 8f, 5100f, 2);
            return new Color(c, c, c, 1f);
        }, false, true);
    }

    static Texture2D CrateTexture()
    {
        return MakeTexture("Assets/Textures/Surfaces/T_CrateWood.png", 128, (u, v, r) =>
        {
            int b = Mathf.FloorToInt(v * 5f);
            float inB = v * 5f - b;
            float c = 0.8f + Hash(b, 41) * 0.15f;
            c *= 0.9f + 0.1f * TileFbm(u, v * 0.3f, 6f, 6100f, 2);
            if (inB < 0.06f) c *= 0.5f;
            bool frame = u < 0.1f || u > 0.9f || v < 0.1f || v > 0.9f;
            bool brace = Mathf.Abs(u - v) < 0.06f;
            if (frame || brace) c *= 0.72f;
            if (frame && (u < 0.012f || u > 0.988f || v < 0.012f || v > 0.988f)) c *= 0.6f;
            return new Color(c, c, c, 1f);
        }, false, true);
    }

    static Texture2D NetTexture()
    {
        return MakeTexture("Assets/Textures/Surfaces/T_FishingNet.png", 256, (u, v, r) =>
        {
            float a = Mathf.Repeat((u + v) * 10f, 1f), b = Mathf.Repeat((u - v) * 10f, 1f);
            float line = Mathf.Max(1f - SS(0.02f, 0.06f, Mathf.Min(a, 1f - a)), 1f - SS(0.02f, 0.06f, Mathf.Min(b, 1f - b)));
            float knot = (1f - SS(0.03f, 0.08f, Mathf.Min(a, 1f - a))) * (1f - SS(0.03f, 0.08f, Mathf.Min(b, 1f - b)));
            float c = 0.85f - knot * 0.3f;
            return new Color(c, c, c, line);
        }, true, true);
    }

    static Texture2D AwningTexture()
    {
        return MakeTexture("Assets/Textures/Surfaces/T_AwningStripes.png", 128, (u, v, r) =>
        {
            bool stripe = Mathf.Repeat(u * 6f, 1f) < 0.5f;
            Color c = stripe ? new Color(0.72f, 0.22f, 0.18f) : new Color(0.93f, 0.88f, 0.78f);
            c *= 0.92f + 0.08f * TileFbm(u, v, 8f, 7100f, 2);
            c.a = 1f; return c;
        }, false, true);
    }

    static float WaterHeight(float u, float v)
    {
        return TileFbm(u, v, 5f, 8100f, 4) + 0.5f * TileFbm(u, v, 13f, 8300f, 2);
    }

    static Texture2D WaterNormalTexture()
    {
        const float e = 1f / 256f;
        return MakeTexture("Assets/Textures/Surfaces/T_SeaRipples_Normal.png", 256, (u, v, r) =>
        {
            float h = WaterHeight(u, v);
            float dx = (WaterHeight(Mathf.Repeat(u + e, 1f), v) - h) * 18f;
            float dy = (WaterHeight(u, Mathf.Repeat(v + e, 1f)) - h) * 18f;
            Vector3 n = new Vector3(-dx, -dy, 1f).normalized;
            return new Color(n.x * 0.5f + 0.5f, n.y * 0.5f + 0.5f, n.z * 0.5f + 0.5f, 1f);
        }, false, true, true);
    }

    static Texture2D WaterColourTexture()
    {
        return MakeTexture("Assets/Textures/Surfaces/T_SeaColour.png", 128, (u, v, r) =>
        {
            float c = 0.85f + 0.15f * TileFbm(u, v, 3f, 8500f, 3);
            return new Color(c, c, c, 1f);
        }, false, true);
    }

    static Texture2D GrassBladeTexture()
    {
        const int size = 128;
        var tex = new Texture2D(size, size, TextureFormat.RGBA32, false);
        var px = new Color[size * size];
        for (int i = 0; i < px.Length; i++) px[i] = new Color(0.4f, 0.45f, 0.2f, 0f);
        var rng = new System.Random(7);
        for (int b = 0; b < 24; b++)
        {
            float bx = 8 + (float)rng.NextDouble() * 112f;
            float h = 55 + (float)rng.NextDouble() * 70f;
            float w = 1.5f + (float)rng.NextDouble() * 2.5f;
            float lean = ((float)rng.NextDouble() - 0.5f) * 50f;
            float shade = 0.75f + (float)rng.NextDouble() * 0.45f;
            for (int y = 0; y < (int)h && y < size; y++)
            {
                float t = y / h;
                float cx = bx + lean * t * t;
                float hw = w * (1f - t) + 0.4f;
                for (int x = Mathf.FloorToInt(cx - hw); x <= Mathf.CeilToInt(cx + hw); x++)
                {
                    if (x < 0 || x >= size) continue;
                    Color c = Color.Lerp(new Color(0.25f, 0.30f, 0.10f), new Color(0.72f, 0.66f, 0.34f), t) * shade;
                    c.a = 1f;
                    px[y * size + x] = c;
                }
            }
        }
        tex.SetPixels(px); tex.Apply();
        string path = "Assets/Textures/Terrain/T_DuneGrassBlades.png";
        File.WriteAllBytes(path, tex.EncodeToPNG());
        Object.DestroyImmediate(tex);
        AssetDatabase.ImportAsset(path);
        var imp = (TextureImporter)AssetImporter.GetAtPath(path);
        imp.wrapMode = TextureWrapMode.Clamp;
        imp.alphaIsTransparency = true;
        imp.SaveAndReimport();
        return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    }

    static Texture2D SoftDotTexture()
    {
        return MakeTexture("Assets/Textures/Effects/T_SoftDot.png", 64, (u, v, r) =>
        {
            float d = Vector2.Distance(new Vector2(u, v), new Vector2(0.5f, 0.5f)) * 2f;
            return new Color(1f, 1f, 1f, Mathf.Pow(Mathf.Clamp01(1f - d), 2.2f));
        }, true, false);
    }

    static Texture2D BeamGradientTexture()
    {
        return MakeTexture("Assets/Textures/Effects/T_BeamFade.png", 64, (u, v, r) =>
        {
            float a = Mathf.Pow(1f - v, 1.5f) * SS(0f, 0.03f, v);
            return new Color(1f, 1f, 1f, a);
        }, true, false);
    }

    // =====================================================================
    // Materials
    // =====================================================================
    static Material Lit(string folder, string name, Color baseColor, float smoothness, Texture2D tex = null, Vector2? tiling = null, Color? emission = null)
    {
        var m = new Material(litShader) { name = name };
        m.SetColor("_BaseColor", baseColor);
        m.SetFloat("_Smoothness", smoothness);
        if (tex != null)
        {
            m.SetTexture("_BaseMap", tex);
            if (tiling.HasValue) m.SetTextureScale("_BaseMap", tiling.Value);
        }
        if (emission.HasValue)
        {
            m.EnableKeyword("_EMISSION");
            m.SetColor("_EmissionColor", emission.Value);
            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
        }
        m.enableInstancing = true;
        AssetDatabase.CreateAsset(m, "Assets/Materials/" + folder + "/" + name + ".mat");
        return m;
    }

    static Material Cutout(string folder, string name, Color baseColor, Texture2D tex, Vector2 tiling)
    {
        var m = Lit(folder, name, baseColor, 0.05f, tex, tiling);
        m.SetFloat("_AlphaClip", 1f);
        m.SetFloat("_Cutoff", 0.45f);
        m.EnableKeyword("_ALPHATEST_ON");
        m.SetFloat("_Cull", 0f);
        m.doubleSidedGI = true;
        m.renderQueue = (int)RenderQueue.AlphaTest;
        m.SetOverrideTag("RenderType", "TransparentCutout");
        EditorUtility.SetDirty(m);
        return m;
    }

    static Material Particle(string name, Texture2D tex, Color colour, bool additive, bool doubleSided)
    {
        var m = new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit")) { name = name };
        m.SetTexture("_BaseMap", tex);
        m.SetColor("_BaseColor", colour);
        m.SetFloat("_Surface", 1f);
        m.SetFloat("_Blend", additive ? 2f : 0f);
        m.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
        m.SetFloat("_DstBlend", additive ? (float)BlendMode.One : (float)BlendMode.OneMinusSrcAlpha);
        m.SetFloat("_ZWrite", 0f);
        if (doubleSided) m.SetFloat("_Cull", 0f);
        m.SetOverrideTag("RenderType", "Transparent");
        m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        m.renderQueue = (int)RenderQueue.Transparent;
        AssetDatabase.CreateAsset(m, "Assets/Materials/Effects/" + name + ".mat");
        return m;
    }

