    // =====================================================================
    // Mesh building
    // =====================================================================
    class MeshBuilder
    {
        public readonly List<Vector3> verts = new List<Vector3>();
        public readonly List<Vector2> uvs = new List<Vector2>();
        public readonly List<List<int>> subs = new List<List<int>>();
        public Matrix4x4 M = Matrix4x4.identity;

        public MeshBuilder(int subMeshes) { for (int i = 0; i < subMeshes; i++) subs.Add(new List<int>()); }

        // Adds a triangle whose front face points away from 'inside'.
        public void Tri(int s, Vector3 a, Vector3 b, Vector3 c, Vector3 inside)
        {
            Vector3 n = Vector3.Cross(b - a, c - a);
            if (n.sqrMagnitude < 1e-12f) return;
            Vector3 centroid = (a + b + c) / 3f;
            if (Vector3.Dot(n, centroid - inside) < 0f) { var t = b; b = c; c = t; }
            var list = subs[s];
            verts.Add(M.MultiplyPoint3x4(a)); uvs.Add(new Vector2(0f, 0f)); list.Add(verts.Count - 1);
            verts.Add(M.MultiplyPoint3x4(b)); uvs.Add(new Vector2(1f, 0f)); list.Add(verts.Count - 1);
            verts.Add(M.MultiplyPoint3x4(c)); uvs.Add(new Vector2(0.5f, 1f)); list.Add(verts.Count - 1);
        }

        // Quad a-b-c-d (in order around the edge) facing 'normal', with UVs measured in metres / uvScale (or 0..1 if uvScale <= 0).
        public void Quad(int s, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector3 normal, float uvScale)
        {
            Vector3 uAxis = (b - a).normalized;
            Vector3 vAxis = Vector3.Cross(normal.normalized, uAxis).normalized;
            if (Vector3.Dot(vAxis, d - a) < 0f) vAxis = -vAxis;
            Vector2 UV(Vector3 p)
            {
                if (uvScale <= 0f)
                {
                    float lu = Vector3.Dot(b - a, uAxis), lv = Mathf.Max(1e-4f, Vector3.Dot(d - a, vAxis));
                    return new Vector2(Vector3.Dot(p - a, uAxis) / lu, Vector3.Dot(p - a, vAxis) / lv);
                }
                return new Vector2(Vector3.Dot(p - a, uAxis) / uvScale, Vector3.Dot(p - a, vAxis) / uvScale);
            }
            AddTri(s, a, b, c, UV(a), UV(b), UV(c), normal);
            AddTri(s, a, c, d, UV(a), UV(c), UV(d), normal);
        }

        public void AddTri(int s, Vector3 a, Vector3 b, Vector3 c, Vector2 ua, Vector2 ub, Vector2 uc, Vector3 normal)
        {
            if (Vector3.Dot(Vector3.Cross(b - a, c - a), normal) < 0f) { var t = b; b = c; c = t; var tu = ub; ub = uc; uc = tu; }
            var list = subs[s];
            verts.Add(M.MultiplyPoint3x4(a)); uvs.Add(ua); list.Add(verts.Count - 1);
            verts.Add(M.MultiplyPoint3x4(b)); uvs.Add(ub); list.Add(verts.Count - 1);
            verts.Add(M.MultiplyPoint3x4(c)); uvs.Add(uc); list.Add(verts.Count - 1);
        }

        public void Box(int s, Vector3 c, Vector3 size, Quaternion rot, float uvScale)
        {
            Vector3 h = size * 0.5f;
            Vector3 X = rot * Vector3.right, Y = rot * Vector3.up, Z = rot * Vector3.forward;
            Vector3 P(float x, float y, float z) { return c + X * (x * h.x) + Y * (y * h.y) + Z * (z * h.z); }
            Quad(s, P(-1, -1, 1), P(1, -1, 1), P(1, 1, 1), P(-1, 1, 1), Z, uvScale);       // front
            Quad(s, P(1, -1, -1), P(-1, -1, -1), P(-1, 1, -1), P(1, 1, -1), -Z, uvScale);  // back
            Quad(s, P(1, -1, 1), P(1, -1, -1), P(1, 1, -1), P(1, 1, 1), X, uvScale);       // right
            Quad(s, P(-1, -1, -1), P(-1, -1, 1), P(-1, 1, 1), P(-1, 1, -1), -X, uvScale);  // left
            Quad(s, P(-1, 1, 1), P(1, 1, 1), P(1, 1, -1), P(-1, 1, -1), Y, uvScale);       // top
            Quad(s, P(-1, -1, -1), P(1, -1, -1), P(1, -1, 1), P(-1, -1, 1), -Y, uvScale);  // bottom
        }

        public void Box(int s, Vector3 c, Vector3 size, float uvScale = 1f) { Box(s, c, size, Quaternion.identity, uvScale); }

        public void Cylinder(int s, Vector3 b, float r0, float r1, float h, int sides, float rot = 0f, bool caps = true)
        {
            Vector3 top = b + Vector3.up * h;
            Vector3 inside = b + Vector3.up * h * 0.5f;
            for (int i = 0; i < sides; i++)
            {
                float a0 = rot + i * Mathf.PI * 2f / sides, a1 = rot + (i + 1) * Mathf.PI * 2f / sides;
                Vector3 p0 = b + new Vector3(Mathf.Cos(a0) * r0, 0f, Mathf.Sin(a0) * r0);
                Vector3 p1 = b + new Vector3(Mathf.Cos(a1) * r0, 0f, Mathf.Sin(a1) * r0);
                Vector3 q0 = top + new Vector3(Mathf.Cos(a0) * r1, 0f, Mathf.Sin(a0) * r1);
                Vector3 q1 = top + new Vector3(Mathf.Cos(a1) * r1, 0f, Mathf.Sin(a1) * r1);
                Vector3 outward = new Vector3(Mathf.Cos((a0 + a1) * 0.5f), 0f, Mathf.Sin((a0 + a1) * 0.5f));
                float circ = 2f * Mathf.PI * Mathf.Max(r0, r1);
                Vector2 u0 = new Vector2(i / (float)sides * circ, 0f), u1 = new Vector2((i + 1) / (float)sides * circ, 0f);
                AddTri(s, p0, p1, q1, u0, u1, u1 + Vector2.up * h, outward + Vector3.up * (r0 - r1) / Mathf.Max(h, 0.001f));
                if (r1 > 0f) AddTri(s, p0, q1, q0, u0, u1 + Vector2.up * h, u0 + Vector2.up * h, outward + Vector3.up * (r0 - r1) / Mathf.Max(h, 0.001f));
                if (caps && r1 > 0f) Tri(s, top, q0, q1, b);
                if (caps && r0 > 0f) Tri(s, b, p0, p1, top);
            }
        }

        public void Cone(int s, Vector3 b, float r, float h, int sides, float rot, float jitter, System.Random rng)
        {
            Vector3 apex = b + Vector3.up * h;
            Vector3 inside = b + Vector3.up * h * 0.3f;
            var ring = new Vector3[sides];
            for (int i = 0; i < sides; i++)
            {
                float a = rot + i * Mathf.PI * 2f / sides;
                float rr = r * (1f + ((float)rng.NextDouble() - 0.5f) * jitter);
                float dy = -((float)rng.NextDouble()) * jitter * r * 0.25f;
                ring[i] = b + new Vector3(Mathf.Cos(a) * rr, dy, Mathf.Sin(a) * rr);
            }
            Vector3 under = b + Vector3.up * h * 0.12f;
            for (int i = 0; i < sides; i++)
            {
                Vector3 p0 = ring[i], p1 = ring[(i + 1) % sides];
                Tri(s, p0, p1, apex, inside);
                Tri(s, under, p1, p0, apex);
            }
        }

        public void Blob(int s, Vector3 c, float r, int lat, int lon, float noise, System.Random rng)
        {
            var grid = new Vector3[lat + 1, lon];
            for (int i = 0; i <= lat; i++)
            {
                float phi = Mathf.PI * i / lat;
                for (int j = 0; j < lon; j++)
                {
                    float th = Mathf.PI * 2f * j / lon;
                    float rr = r * (1f + ((float)rng.NextDouble() - 0.5f) * noise);
                    if (i == 0 || i == lat) rr = r;
                    grid[i, j] = c + new Vector3(Mathf.Sin(phi) * Mathf.Cos(th), Mathf.Cos(phi), Mathf.Sin(phi) * Mathf.Sin(th)) * rr;
                }
            }
            for (int i = 0; i < lat; i++)
                for (int j = 0; j < lon; j++)
                {
                    int j1 = (j + 1) % lon;
                    Tri(s, grid[i, j], grid[i, j1], grid[i + 1, j1], c);
                    Tri(s, grid[i, j], grid[i + 1, j1], grid[i + 1, j], c);
                }
        }

        public void Torus(int s, Vector3 c, float R, float r, int segs, int sides)
        {
            for (int i = 0; i < segs; i++)
                for (int j = 0; j < sides; j++)
                {
                    Vector3 P(int a, int b)
                    {
                        float u = a * Mathf.PI * 2f / segs, v = b * Mathf.PI * 2f / sides;
                        return c + new Vector3((R + r * Mathf.Cos(v)) * Mathf.Cos(u), r * Mathf.Sin(v), (R + r * Mathf.Cos(v)) * Mathf.Sin(u));
                    }
                    float um = (i + 0.5f) * Mathf.PI * 2f / segs;
                    Vector3 ringCentre = c + new Vector3(R * Mathf.Cos(um), 0f, R * Mathf.Sin(um));
                    Tri(s, P(i, j), P(i + 1, j), P(i + 1, j + 1), ringCentre);
                    Tri(s, P(i, j), P(i + 1, j + 1), P(i, j + 1), ringCentre);
                }
        }

        public Mesh Save(string path)
        {
            var mesh = new Mesh { name = Path.GetFileNameWithoutExtension(path) };
            if (verts.Count > 65000) mesh.indexFormat = IndexFormat.UInt32;
            mesh.SetVertices(verts);
            mesh.SetUVs(0, uvs);
            mesh.subMeshCount = subs.Count;
            for (int i = 0; i < subs.Count; i++) mesh.SetTriangles(subs[i], i);
            mesh.RecalculateNormals();
            mesh.RecalculateTangents();
            mesh.RecalculateBounds();
            AssetDatabase.CreateAsset(mesh, path);
            return mesh;
        }
    }

    // ---------------------------------------------------------------- nature meshes
    static Mesh PineMesh(string name, int tiers, float baseRadius, float step, float coneHeight, int seed)
    {
        var rng = new System.Random(seed);
        var mb = new MeshBuilder(2);
        mb.Cylinder(0, Vector3.zero, 0.24f, 0.1f, step * tiers + 1.5f, 6);
        for (int i = 0; i < tiers; i++)
        {
            float t = i / (float)Mathf.Max(1, tiers - 1);
            float r = Mathf.Lerp(baseRadius, baseRadius * 0.35f, t);
            mb.Cone(1, new Vector3(0f, 1.8f + i * step, 0f), r, coneHeight * Mathf.Lerp(1f, 0.8f, t), 7, (float)rng.NextDouble() * 6f, 0.25f, rng);
        }
        return mb.Save("Assets/Meshes/Nature/" + name + ".asset");
    }

    static Mesh BroadleafMesh(string name, int seed)
    {
        var rng = new System.Random(seed);
        var mb = new MeshBuilder(2);
        mb.Cylinder(0, Vector3.zero, 0.32f, 0.2f, 3.6f, 7);
        for (int i = 0; i < 3; i++)
        {
            float ang = i * 120f + (float)rng.NextDouble() * 30f;
            mb.M = Matrix4x4.TRS(new Vector3(0f, 2.6f, 0f), Quaternion.Euler(0f, ang, 36f), Vector3.one);
            mb.Cylinder(0, Vector3.zero, 0.12f, 0.06f, 1.8f, 5);
        }
        mb.M = Matrix4x4.identity;
        mb.Blob(1, new Vector3(0f, 5.2f, 0f), 2.0f, 5, 8, 0.3f, rng);
        for (int i = 0; i < 4; i++)
        {
            float ang = (i * 90f + (float)rng.NextDouble() * 40f) * Mathf.Deg2Rad;
            Vector3 c = new Vector3(Mathf.Cos(ang) * 1.4f, 4.3f + (float)rng.NextDouble() * 0.8f, Mathf.Sin(ang) * 1.4f);
            mb.Blob(1, c, 1.4f + (float)rng.NextDouble() * 0.5f, 5, 7, 0.35f, rng);
        }
        return mb.Save("Assets/Meshes/Nature/" + name + ".asset");
    }

    static Mesh RockMesh(string name, int seed)
    {
        var rng = new System.Random(seed);
        var mb = new MeshBuilder(1);
        mb.M = Matrix4x4.Scale(new Vector3(1f, 0.62f, 0.85f));
        mb.Blob(0, Vector3.zero, 1f, 5, 8, 0.42f, rng);
        return mb.Save("Assets/Meshes/Nature/" + name + ".asset");
    }

    // ---------------------------------------------------------------- house
    // Sub-meshes: 0 walls, 1 roof, 2 trim, 3 windows, 4 stone, 5 door
    static Mesh HouseMesh(string name, float W, float D, float H, float rh, bool boathouse)
    {
        var mb = new MeshBuilder(6);
        Vector3 chimneyTop = Vector3.zero;
        float floorY = 0.4f;
        float top = floorY + H;
        // Foundation sinks into the slope so the house never floats
        mb.Box(4, new Vector3(0f, -0.8f, 0f), new Vector3(W + 0.3f, 2.4f, D + 0.3f), 1.5f);
        // Walls
        mb.Box(0, new Vector3(0f, floorY + H * 0.5f, 0f), new Vector3(W, H, D), 2f);
        // Gables (front faces +z, towards the sea)
        foreach (float sgn in new[] { 1f, -1f })
        {
            Vector3 a = new Vector3(-W * 0.5f, top, sgn * D * 0.5f), b = new Vector3(W * 0.5f, top, sgn * D * 0.5f), c = new Vector3(0f, top + rh, sgn * D * 0.5f);
            Vector3 n = new Vector3(0f, 0f, sgn);
            mb.AddTri(0, a, b, c, new Vector2(a.x / 2f, a.y / 2f), new Vector2(b.x / 2f, b.y / 2f), new Vector2(c.x / 2f, c.y / 2f), n);
        }
        // Roof slabs with overhang
        float ang = Mathf.Atan2(rh, W * 0.5f);
        float slope = (W * 0.5f) / Mathf.Cos(ang) + 0.55f;
        Vector3 ridge = new Vector3(0f, top + rh, 0f);
        foreach (float sgn in new[] { 1f, -1f })
        {
            Vector3 down = new Vector3(sgn * Mathf.Cos(ang), -Mathf.Sin(ang), 0f);
            Vector3 up = new Vector3(sgn * Mathf.Sin(ang), Mathf.Cos(ang), 0f);
            Vector3 c = ridge + down * (slope * 0.5f - 0.05f) + up * 0.11f;
            mb.Box(1, c, new Vector3(slope, 0.18f, D + 0.9f), Quaternion.Euler(0f, 0f, -sgn * ang * Mathf.Rad2Deg), 2f);
        }
        mb.Box(2, ridge + Vector3.up * 0.2f, new Vector3(0.32f, 0.22f, D + 0.95f), 1f);
        // Barge boards along the gable edges
        foreach (float sgn in new[] { 1f, -1f })
            foreach (float side in new[] { 1f, -1f })
            {
                Vector3 mid = new Vector3(side * W * 0.25f, top + rh * 0.5f + 0.05f, sgn * (D * 0.5f + 0.47f));
                mb.Box(2, mid, new Vector3(slope - 0.4f, 0.22f, 0.08f), Quaternion.Euler(0f, 0f, -side * ang * Mathf.Rad2Deg), 1f);
            }
        // Corner boards
        foreach (float sx in new[] { -1f, 1f })
            foreach (float sz in new[] { -1f, 1f })
                mb.Box(2, new Vector3(sx * (W * 0.5f), floorY + H * 0.5f, sz * (D * 0.5f)), new Vector3(0.22f, H, 0.22f), 1f);

        float fz = D * 0.5f;
        if (boathouse)
        {
            // Big double doors facing the water
            mb.Box(5, new Vector3(0f, floorY + 1.5f, fz + 0.04f), new Vector3(W * 0.55f, 3.0f, 0.08f), 1f);
            mb.Box(2, new Vector3(0f, floorY + 1.6f, fz + 0.02f), new Vector3(W * 0.55f + 0.3f, 3.25f, 0.06f), 1f);
            mb.Box(2, new Vector3(0f, floorY + 1.5f, fz + 0.09f), new Vector3(0.1f, 3.0f, 0.04f), 1f);
            Window(mb, new Vector3(0f, top + rh * 0.4f, fz), Vector3.forward, 0.7f, 0.7f);
        }
        else
        {
            float doorX = W > 5f ? -W * 0.18f : 0f;
            mb.Box(5, new Vector3(doorX, floorY + 1.0f, fz + 0.04f), new Vector3(0.95f, 2.0f, 0.08f), 1f);
            mb.Box(2, new Vector3(doorX, floorY + 1.08f, fz + 0.02f), new Vector3(1.2f, 2.25f, 0.06f), 1f);
            mb.Box(4, new Vector3(doorX, floorY - 0.2f, fz + 0.45f), new Vector3(1.5f, 0.4f, 0.9f), 1f); // step
            if (W > 5f) Window(mb, new Vector3(W * 0.22f, floorY + 1.55f, fz), Vector3.forward, 1.0f, 1.1f);
            else
            {
                Window(mb, new Vector3(-W * 0.3f, floorY + 1.55f, fz), Vector3.forward, 0.7f, 0.9f);
                Window(mb, new Vector3(W * 0.3f, floorY + 1.55f, fz), Vector3.forward, 0.7f, 0.9f);
            }
            if (H > 4.5f)
            {
                Window(mb, new Vector3(-W * 0.22f, floorY + 3.9f, fz), Vector3.forward, 0.9f, 1.0f);
                Window(mb, new Vector3(W * 0.22f, floorY + 3.9f, fz), Vector3.forward, 0.9f, 1.0f);
            }
            Window(mb, new Vector3(0f, top + rh * 0.38f, fz), Vector3.forward, 0.6f, 0.7f);
            // Chimney through the roof
            Vector3 ch = new Vector3(W * 0.2f, top + rh * 0.55f + 0.5f, -D * 0.22f);
            mb.Box(4, ch, new Vector3(0.75f, rh + 1.4f, 0.75f), 1f);
            mb.Box(2, ch + Vector3.up * (rh * 0.5f + 0.75f), new Vector3(0.95f, 0.15f, 0.95f), 1f);
            chimneyTop = ch + Vector3.up * (rh * 0.5f + 0.85f);
        }
        // Side windows
        int sideCount = D > 7f ? 2 : 1;
        for (int i = 0; i < sideCount; i++)
        {
            float z = sideCount == 1 ? 0f : (i == 0 ? -D * 0.22f : D * 0.22f);
            Window(mb, new Vector3(W * 0.5f, floorY + 1.55f, z), Vector3.right, 0.9f, 1.0f);
            Window(mb, new Vector3(-W * 0.5f, floorY + 1.55f, z), Vector3.left, 0.9f, 1.0f);
            if (H > 4.5f)
            {
                Window(mb, new Vector3(W * 0.5f, floorY + 3.9f, z), Vector3.right, 0.9f, 1.0f);
                Window(mb, new Vector3(-W * 0.5f, floorY + 3.9f, z), Vector3.left, 0.9f, 1.0f);
            }
        }
        // Back window
        Window(mb, new Vector3(0f, floorY + 1.55f, -fz), Vector3.back, 0.9f, 1.0f);
        var mesh = mb.Save("Assets/Meshes/Buildings/" + name + ".asset");
        if (!boathouse) chimneyTops[mesh] = chimneyTop;
        return mesh;
    }

    static void Window(MeshBuilder mb, Vector3 centre, Vector3 outward, float w, float h)
    {
        Quaternion rot = Quaternion.LookRotation(outward, Vector3.up);
        mb.Box(2, centre + outward * 0.03f, new Vector3(w + 0.24f, h + 0.24f, 0.06f), rot, 1f);
        mb.Box(3, centre + outward * 0.07f, new Vector3(w, h, 0.04f), rot, -1f);
        mb.Box(2, centre + outward * 0.1f, new Vector3(0.06f, h, 0.03f), rot, 1f);
        mb.Box(2, centre + outward * 0.1f, new Vector3(w, 0.06f, 0.03f), rot, 1f);
        mb.Box(2, centre + outward * 0.1f + Vector3.down * (h * 0.5f + 0.08f), new Vector3(w + 0.3f, 0.08f, 0.16f), rot, 1f); // sill
    }

    // ---------------------------------------------------------------- boats
    // Sub-meshes: 0 hull paint, 1 interior wood, 2 dark trim, 3 stripe, 4 cabin/sail, 5 glass
    static MeshBuilder HullBuilder(float L, float B, float freeboard, float sheer, float draft)
    {
        var mb = new MeshBuilder(6);
        const int N = 18;
        var outer = new Vector3[N + 1, 9];
        var inner = new Vector3[N + 1, 9];
        for (int i = 0; i <= N; i++)
        {
            float t = i / (float)N;
            float s = Mathf.Sin(Mathf.PI * t);
            float z = (t - 0.5f) * L;
            float b = B * Mathf.Pow(s, 0.55f);
            float g = freeboard + sheer * Mathf.Pow(2f * t - 1f, 2f);
            float k = -draft * Mathf.Pow(s, 0.4f);
            Vector2[] half =
            {
                new Vector2(-b, g), new Vector2(-b * 0.97f, g * 0.35f), new Vector2(-b * 0.78f, k * 0.55f),
                new Vector2(-b * 0.38f, k * 0.95f), new Vector2(0f, k)
            };
            for (int j = 0; j < 9; j++)
            {
                Vector2 p = j <= 4 ? half[j] : new Vector2(-half[8 - j].x, half[8 - j].y);
                outer[i, j] = new Vector3(p.x, p.y, z);
                float shrink = b > 0.08f ? (b - 0.06f) / b : 0f;
                inner[i, j] = new Vector3(p.x * shrink, Mathf.Max(p.y + 0.06f, k + 0.08f) + (j == 0 || j == 8 ? -0.06f : 0f), z);
                if (j == 0 || j == 8) inner[i, j].y = p.y;
            }
        }
        for (int i = 0; i < N; i++)
            for (int j = 0; j < 8; j++)
            {
                Vector3 axis = new Vector3(0f, 0.2f, (outer[i, 0].z + outer[i + 1, 0].z) * 0.5f);
                int sub = (j == 0 || j == 7) ? 3 : 0;
                mb.Tri(sub, outer[i, j], outer[i + 1, j], outer[i + 1, j + 1], axis);
                mb.Tri(sub, outer[i, j], outer[i + 1, j + 1], outer[i, j + 1], axis);
                Vector3 cen = (inner[i, j] + inner[i + 1, j + 1]) * 0.5f;
                Vector3 away = cen * 2f - new Vector3(0f, freeboard + 0.5f, cen.z);
                mb.Tri(1, inner[i, j], inner[i + 1, j], inner[i + 1, j + 1], away);
                mb.Tri(1, inner[i, j], inner[i + 1, j + 1], inner[i, j + 1], away);
            }
        // Gunwale caps
        for (int i = 0; i < N; i++)
            foreach (int j in new[] { 0, 8 })
            {
                Vector3 below = (outer[i, j] + outer[i + 1, j]) * 0.5f + Vector3.down;
                Vector3 o0 = outer[i, j] + Vector3.up * 0.04f, o1 = outer[i + 1, j] + Vector3.up * 0.04f;
                Vector3 n0 = inner[i, j] + Vector3.up * 0.04f, n1 = inner[i + 1, j] + Vector3.up * 0.04f;
                mb.Tri(2, o0, o1, n1, below);
                mb.Tri(2, o0, n1, n0, below);
            }
        // Stem and stern posts
        foreach (float sgn in new[] { -1f, 1f })
        {
            float g = freeboard + sheer;
            mb.Box(2, new Vector3(0f, g * 0.5f - draft * 0.2f, sgn * L * 0.5f), new Vector3(0.1f, g + draft * 0.4f + 0.2f, 0.14f), 1f);
        }
        // Keel strip and floor boards
        mb.Box(2, new Vector3(0f, -draft - 0.03f, 0f), new Vector3(0.08f, 0.08f, L * 0.82f), 1f);
        mb.Box(1, new Vector3(0f, -draft + 0.14f, 0f), new Vector3(B * 0.7f, 0.04f, L * 0.6f), 1f);
        return mb;
    }

    static void Thwart(MeshBuilder mb, float B, float L, float t, float y)
    {
        float s = Mathf.Sin(Mathf.PI * t);
        float b = B * Mathf.Pow(s, 0.55f) * 0.94f;
        mb.Box(1, new Vector3(0f, y, (t - 0.5f) * L), new Vector3(b * 2f, 0.05f, 0.28f), 1f);
    }

    static Mesh RowboatMesh()
    {
        float L = 4.6f, B = 0.72f;
        var mb = HullBuilder(L, B, 0.42f, 0.22f, 0.22f);
        Thwart(mb, B, L, 0.3f, 0.22f);
        Thwart(mb, B, L, 0.55f, 0.22f);
        Thwart(mb, B, L, 0.8f, 0.22f);
        // Oars resting across the boat
        mb.M = Matrix4x4.TRS(new Vector3(0.15f, 0.36f, 0.2f), Quaternion.Euler(0f, 8f, 0f), Vector3.one);
        mb.Box(1, Vector3.zero, new Vector3(0.06f, 0.05f, 3.2f), 1f);
        mb.Box(1, new Vector3(0f, 0f, 1.45f), new Vector3(0.16f, 0.02f, 0.55f), 1f);
        mb.M = Matrix4x4.identity;
        return mb.Save("Assets/Meshes/Boats/SM_Rowboat.asset");
    }

    static Mesh FishingBoatMesh()
    {
        float L = 8.4f, B = 1.3f;
        var mb = HullBuilder(L, B, 0.75f, 0.35f, 0.5f);
        // Deck, wheelhouse, mast with a boom and net drum
        mb.Box(1, new Vector3(0f, 0.55f, 0f), new Vector3(B * 1.75f, 0.06f, L * 0.72f), 1.5f);
        mb.Box(4, new Vector3(0f, 1.45f, -1.6f), new Vector3(1.6f, 1.7f, 1.7f), 1f);
        mb.Box(2, new Vector3(0f, 2.36f, -1.6f), new Vector3(1.85f, 0.12f, 2.0f), 1f);
        mb.Box(5, new Vector3(0f, 1.75f, -0.73f), new Vector3(1.3f, 0.55f, 0.04f), -1f);
        mb.Box(5, new Vector3(0.81f, 1.75f, -1.6f), new Vector3(0.04f, 0.55f, 1.2f), -1f);
        mb.Box(5, new Vector3(-0.81f, 1.75f, -1.6f), new Vector3(0.04f, 0.55f, 1.2f), -1f);
        mb.Cylinder(2, new Vector3(0f, 0.55f, 1.2f), 0.09f, 0.06f, 5.2f, 6);
        mb.M = Matrix4x4.TRS(new Vector3(0f, 2.2f, 1.2f), Quaternion.Euler(-60f, 0f, 0f), Vector3.one);
        mb.Cylinder(2, Vector3.zero, 0.06f, 0.04f, 3.0f, 5);
        mb.M = Matrix4x4.TRS(new Vector3(0f, 1.0f, 2.6f), Quaternion.Euler(0f, 0f, 90f), Vector3.one);
        mb.Cylinder(2, new Vector3(0f, -0.5f, 0f), 0.32f, 0.32f, 1.0f, 10);
        mb.M = Matrix4x4.identity;
        return mb.Save("Assets/Meshes/Boats/SM_FishingBoat.asset");
