    static Mesh SailboatMesh()
    {
        float L = 9.2f, B = 1.45f;
        var mb = HullBuilder(L, B, 0.7f, 0.4f, 0.55f);
        mb.Box(1, new Vector3(0f, 0.5f, 0.8f), new Vector3(B * 1.75f, 0.06f, L * 0.5f), 1.5f);
        Thwart(mb, B, L, 0.25f, 0.45f);
        mb.Cylinder(2, new Vector3(0f, 0.5f, 1.0f), 0.11f, 0.07f, 8.2f, 6);
        // Furled sail lashed to the boom
        mb.Cylinder(2, new Vector3(0f, 1.55f, 1.0f), 0.06f, 0.06f, 0.01f, 5);
        mb.M = Matrix4x4.TRS(new Vector3(0f, 1.55f, 1.0f), Quaternion.Euler(-90f, 0f, 0f), Vector3.one);
        mb.Cylinder(2, Vector3.zero, 0.06f, 0.06f, 3.8f, 6);
        mb.Cylinder(4, new Vector3(0f, 0.2f, 0.22f), 0.2f, 0.13f, 3.3f, 7);
        mb.M = Matrix4x4.identity;
        return mb.Save("Assets/Meshes/Boats/SM_Sailboat.asset");
    }

    // ---------------------------------------------------------------- props
    static Mesh BarrelMesh()
    {
        var mb = new MeshBuilder(2);
        const float H = 0.95f;
        const int segs = 6;
        for (int i = 0; i < segs; i++)
        {
            float y0 = i * H / segs, y1 = (i + 1) * H / segs;
            float r0 = 0.30f + 0.06f * Mathf.Sin(Mathf.PI * y0 / H), r1 = 0.30f + 0.06f * Mathf.Sin(Mathf.PI * y1 / H);
            mb.Cylinder(0, new Vector3(0f, y0, 0f), r0, r1, y1 - y0, 12, 0f, i == 0 || i == segs - 1);
        }
        foreach (float y in new[] { 0.1f, 0.33f, 0.62f, 0.85f })
        {
            float r = 0.30f + 0.06f * Mathf.Sin(Mathf.PI * y / H) + 0.012f;
            mb.Cylinder(1, new Vector3(0f, y - 0.025f, 0f), r, r, 0.05f, 12, 0f, false);
        }
        return mb.Save("Assets/Meshes/Props/SM_Barrel.asset");
    }

