    // Shallow fish box with fish inside: 0 wood, 1 fish
    static Mesh FishBoxMesh()
    {
        var mb = new MeshBuilder(2);
        var rng = new System.Random(31);
        mb.Box(0, new Vector3(0f, 0.03f, 0f), new Vector3(0.9f, 0.06f, 0.6f), -1f);
        mb.Box(0, new Vector3(0f, 0.15f, 0.29f), new Vector3(0.9f, 0.24f, 0.04f), -1f);
        mb.Box(0, new Vector3(0f, 0.15f, -0.29f), new Vector3(0.9f, 0.24f, 0.04f), -1f);
        mb.Box(0, new Vector3(0.43f, 0.15f, 0f), new Vector3(0.04f, 0.24f, 0.6f), -1f);
        mb.Box(0, new Vector3(-0.43f, 0.15f, 0f), new Vector3(0.04f, 0.24f, 0.6f), -1f);
        for (int i = 0; i < 9; i++)
        {
            mb.M = Matrix4x4.TRS(new Vector3(((float)rng.NextDouble() - 0.5f) * 0.55f, 0.12f + i * 0.008f, ((float)rng.NextDouble() - 0.5f) * 0.35f),
                Quaternion.Euler(0f, (float)rng.NextDouble() * 180f, 90f), new Vector3(0.07f, 0.06f, 0.3f));
            mb.Blob(1, Vector3.zero, 1f, 3, 6, 0.05f, rng);
