    static Mesh LobsterPotMesh()
    {
        // 0 wood frame, 1 net
        var mb = new MeshBuilder(2);
        mb.Box(0, new Vector3(0f, 0.03f, 0f), new Vector3(0.75f, 0.06f, 0.5f), 1f);
        foreach (float z in new[] { -0.22f, 0f, 0.22f })
        {
            mb.M = Matrix4x4.TRS(new Vector3(0f, 0.06f, z), Quaternion.Euler(0f, 0f, 0f), Vector3.one);
            for (int i = 0; i < 6; i++)
            {
                float a0 = Mathf.PI * i / 6f, a1 = Mathf.PI * (i + 1) / 6f;
                Vector3 p0 = new Vector3(Mathf.Cos(a0) * 0.36f, Mathf.Sin(a0) * 0.36f, 0f), p1 = new Vector3(Mathf.Cos(a1) * 0.36f, Mathf.Sin(a1) * 0.36f, 0f);
                mb.Box(0, (p0 + p1) * 0.5f, new Vector3((p1 - p0).magnitude + 0.02f, 0.03f, 0.03f), Quaternion.Euler(0f, 0f, (a0 + a1) * 0.5f * Mathf.Rad2Deg + 90f), 1f);
            }
        }
        mb.M = Matrix4x4.identity;
        for (int i = 0; i < 6; i++)
        {
            float a0 = Mathf.PI * i / 6f, a1 = Mathf.PI * (i + 1) / 6f;
            Vector3 p0 = new Vector3(Mathf.Cos(a0) * 0.35f, 0.06f + Mathf.Sin(a0) * 0.35f, -0.24f), p1 = new Vector3(Mathf.Cos(a1) * 0.35f, 0.06f + Mathf.Sin(a1) * 0.35f, -0.24f);
            Vector3 n = new Vector3(Mathf.Cos((a0 + a1) * 0.5f), Mathf.Sin((a0 + a1) * 0.5f), 0f);
            mb.Quad(1, p0, p1, p1 + Vector3.forward * 0.48f, p0 + Vector3.forward * 0.48f, n, 0.5f);
        }
        return mb.Save("Assets/Meshes/Props/SM_LobsterPot.asset");
    }

