    // Gull: 0 white body/wings, 1 dark wingtips. Faces +z.
    static Mesh GullMesh()
    {
        var mb = new MeshBuilder(2);
        var rng = new System.Random(3);
        mb.M = Matrix4x4.Scale(new Vector3(0.09f, 0.09f, 0.28f));
        mb.Blob(0, Vector3.zero, 1f, 4, 6, 0f, rng);
        mb.M = Matrix4x4.identity;
        foreach (float s in new[] { -1f, 1f })
        {
            Vector3 root0 = new Vector3(s * 0.05f, 0.02f, 0.1f), root1 = new Vector3(s * 0.05f, 0.02f, -0.06f);
            Vector3 elbow0 = new Vector3(s * 0.32f, 0.1f, 0.06f), elbow1 = new Vector3(s * 0.32f, 0.1f, -0.08f);
            Vector3 tip = new Vector3(s * 0.62f, 0.04f, -0.08f);
            foreach (Vector3 n in new[] { Vector3.up, Vector3.down })
            {
                mb.AddTri(0, root0, elbow0, elbow1, Vector2.zero, Vector2.right, Vector2.one, n);
                mb.AddTri(0, root0, elbow1, root1, Vector2.zero, Vector2.one, Vector2.up, n);
                mb.AddTri(1, elbow0, tip, elbow1, Vector2.zero, Vector2.right, Vector2.one, n);
            }
        }
        return mb.Save("Assets/Meshes/Props/SM_Seagull.asset");
    }

    // Lighthouse: 0 white, 1 red, 2 stone, 3 lamp glass, 4 dark metal. Origin at ground.
    static Mesh LighthouseMesh()
    {
        var mb = new MeshBuilder(5);
        mb.Cylinder(2, new Vector3(0f, -1.5f, 0f), 3.5f, 3.3f, 3.5f, 12);
        const float bandH = 4f;
        for (int i = 0; i < 4; i++)
        {
            float y0 = 2f + i * bandH;
            float r0 = Mathf.Lerp(2.6f, 1.8f, i / 4f), r1 = Mathf.Lerp(2.6f, 1.8f, (i + 1) / 4f);
            mb.Cylinder(i % 2 == 0 ? 0 : 1, new Vector3(0f, y0, 0f), r0, r1, bandH, 16, 0f, false);
        }
        mb.Cylinder(4, new Vector3(0f, 18f, 0f), 2.7f, 2.7f, 0.3f, 16);
        for (int i = 0; i < 16; i++)
        {
            float a = i * Mathf.PI * 2f / 16f, a1 = (i + 1) * Mathf.PI * 2f / 16f;
            Vector3 p = new Vector3(Mathf.Cos(a) * 2.6f, 18.8f, Mathf.Sin(a) * 2.6f);
            mb.Box(4, p, new Vector3(0.06f, 1.0f, 0.06f), 1f);
            Vector3 q = new Vector3(Mathf.Cos(a1) * 2.6f, 19.3f, Mathf.Sin(a1) * 2.6f);
            Vector3 mid = (new Vector3(p.x, 19.3f, p.z) + q) * 0.5f;
            mb.Box(4, mid, new Vector3(0.05f, 0.05f, (q - new Vector3(p.x, 19.3f, p.z)).magnitude + 0.05f), Quaternion.LookRotation(q - new Vector3(p.x, 19.3f, p.z)), 1f);
        }
        mb.Cylinder(4, new Vector3(0f, 18.3f, 0f), 1.5f, 1.5f, 0.5f, 12);
        mb.Cylinder(3, new Vector3(0f, 18.8f, 0f), 1.35f, 1.35f, 1.8f, 12);
        for (int i = 0; i < 8; i++)
        {
            float a = i * Mathf.PI * 2f / 8f;
            mb.Box(4, new Vector3(Mathf.Cos(a) * 1.37f, 19.7f, Mathf.Sin(a) * 1.37f), new Vector3(0.07f, 1.8f, 0.07f), 1f);
        }
        mb.Cylinder(1, new Vector3(0f, 20.6f, 0f), 1.8f, 0f, 1.5f, 16);
        mb.Cylinder(4, new Vector3(0f, 22.0f, 0f), 0.1f, 0.04f, 0.9f, 6);
        mb.Box(4, new Vector3(0f, 3.1f, 2.62f), new Vector3(1.1f, 2.2f, 0.12f), 1f); // door
        for (int i = 0; i < 3; i++)
        {
            float y = 7f + i * 4f;
            float r = Mathf.Lerp(2.6f, 1.8f, (y - 2f) / 16f);
            mb.Box(4, new Vector3(0f, y, r + 0.02f), new Vector3(0.45f, 0.7f, 0.08f), 1f);
        }
        return mb.Save("Assets/Meshes/Buildings/SM_Lighthouse.asset");
    }

    static Mesh BeamMesh()
    {
        var mesh = new Mesh { name = "SM_LighthouseBeam" };
        const int sides = 16;
        const float len = 70f;
        var v = new List<Vector3>(); var uv = new List<Vector2>(); var tris = new List<int>();
        for (int i = 0; i <= sides; i++)
        {
            float a = i * Mathf.PI * 2f / sides;
            Vector3 dir = new Vector3(Mathf.Cos(a), Mathf.Sin(a), 0f);
            v.Add(dir * 0.5f); uv.Add(new Vector2(i / (float)sides, 0f));
            v.Add(dir * 5.5f + Vector3.forward * len); uv.Add(new Vector2(i / (float)sides, 1f));
        }
        for (int i = 0; i < sides; i++)
        {
            int b = i * 2;
            tris.Add(b); tris.Add(b + 1); tris.Add(b + 3);
            tris.Add(b); tris.Add(b + 3); tris.Add(b + 2);
        }
        mesh.SetVertices(v); mesh.SetUVs(0, uv); mesh.SetTriangles(tris, 0);
        mesh.RecalculateNormals(); mesh.RecalculateBounds();
        AssetDatabase.CreateAsset(mesh, "Assets/Meshes/Buildings/SM_LighthouseBeam.asset");
        return mesh;
    }

    static Mesh PierMesh(out List<Vector3> postTops)
    {
        // 0 deck boards, 1 posts and beams (dark), built in world space relative to the pier origin (158, 0, 133)
        var mb = new MeshBuilder(2);
        postTops = new List<Vector3>();
        float deckY = 11.4f;
        var rng = new System.Random(99);
        // Main walkway: x -1.6..1.6, z 0..47
        for (float z = 0f; z < 47f; z += 0.32f)
        {
            float jitter = ((float)rng.NextDouble() - 0.5f) * 0.03f;
            mb.Box(0, new Vector3(jitter, deckY, z + 0.15f), new Vector3(3.3f + ((float)rng.NextDouble() - 0.5f) * 0.15f, 0.08f, 0.28f), Quaternion.Euler(0f, ((float)rng.NextDouble() - 0.5f) * 1.2f, 0f), 1.5f);
        }
        // T-head: x -6..6, z 45..55
        for (float x = -6f; x < 6f; x += 0.32f)
            mb.Box(0, new Vector3(x + 0.15f, deckY + 0.01f, 50f), new Vector3(0.28f, 0.08f, 10.2f + ((float)rng.NextDouble() - 0.5f) * 0.15f), 1.5f);
        // Side jetty: x 1.6..14, z 25.8..28.2
        for (float x = 1.6f; x < 14f; x += 0.32f)
            mb.Box(0, new Vector3(x + 0.15f, deckY - 0.01f, 27f), new Vector3(0.28f, 0.08f, 2.4f), 1.5f);
        // Stringers
        foreach (float x in new[] { -1.4f, 0f, 1.4f }) mb.Box(1, new Vector3(x, deckY - 0.15f, 23.5f), new Vector3(0.18f, 0.22f, 47f), 1f);
        foreach (float z in new[] { 46f, 50f, 54f }) mb.Box(1, new Vector3(0f, deckY - 0.15f, z), new Vector3(12f, 0.22f, 0.18f), 1f);
        mb.Box(1, new Vector3(7.8f, deckY - 0.15f, 26f), new Vector3(12.4f, 0.22f, 0.18f), 1f);
        mb.Box(1, new Vector3(7.8f, deckY - 0.15f, 28f), new Vector3(12.4f, 0.22f, 0.18f), 1f);
        // Posts (bottom computed by caller via terrain; here go deep)
        var posts = new List<Vector3>();
        for (float z = 2f; z <= 46f; z += 4f) { posts.Add(new Vector3(-1.75f, 0f, z)); posts.Add(new Vector3(1.75f, 0f, z)); }
        foreach (float x in new[] { -6f, -2f, 2f, 6f }) { posts.Add(new Vector3(x, 0f, 45.2f)); posts.Add(new Vector3(x, 0f, 54.8f)); }
        foreach (float x in new[] { 6f, 10f, 14f }) { posts.Add(new Vector3(x, 0f, 25.7f)); posts.Add(new Vector3(x, 0f, 28.3f)); }
        foreach (var p in posts)
        {
            float wx = 158f + p.x, wz = 133f + p.z;
            float ground = Ground(wx, wz) - 0.6f;
            float topY = deckY + 0.35f;
            mb.Box(1, new Vector3(p.x, (ground + topY) * 0.5f, p.z), new Vector3(0.3f, topY - ground, 0.3f), 1f);
            postTops.Add(new Vector3(wx, topY, wz));
        }
        // Handrail on the west side of the walkway
        for (float z = 6f; z < 44f; z += 4f)
        {
            mb.Box(1, new Vector3(-1.75f, deckY + 0.55f, z), new Vector3(0.12f, 1.0f, 0.12f), 1f);
        }
        mb.Box(1, new Vector3(-1.75f, deckY + 1.05f, 25f), new Vector3(0.1f, 0.1f, 38.2f), 1f);
        return mb.Save("Assets/Meshes/Props/SM_Pier.asset");
    }

    // =====================================================================
    // Prefabs
    // =====================================================================
    class Prefabs
    {
        public GameObject pine, fir, broadleaf, rockA, rockB, rockC;
        public GameObject houseA, houseB, houseC, boathouse;
        public GameObject rowboat, fishingBoat, sailboat;
        public GameObject barrel, crate, fishBox, rope, lobsterPot, lanternPost, bench, fence, netRack, fishRack, stall, well, cart, bollard, log, signpost, embers, gull;
        public Mesh lantern, lighthouse, beam;
    }

    static GameObject MeshPrefab(string path, Mesh mesh, params Material[] mats)
    {
        var go = new GameObject(Path.GetFileNameWithoutExtension(path));
        go.AddComponent<MeshFilter>().sharedMesh = mesh;
        go.AddComponent<MeshRenderer>().sharedMaterials = mats;
        var prefab = PrefabUtility.SaveAsPrefabAsset(go, path);
        Object.DestroyImmediate(go);
        return prefab;
    }

    static GameObject TreePrefab(string path, Mesh mesh, params Material[] mats)
    {
        var root = new GameObject(Path.GetFileNameWithoutExtension(path));
        var child = new GameObject("Mesh");
        child.transform.SetParent(root.transform, false);
        child.AddComponent<MeshFilter>().sharedMesh = mesh;
        var mr = child.AddComponent<MeshRenderer>();
        mr.sharedMaterials = mats;
        var lod = root.AddComponent<LODGroup>();
        lod.SetLODs(new[] { new LOD(0.004f, new Renderer[] { mr }) });
        lod.RecalculateBounds();
        var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
        Object.DestroyImmediate(root);
        return prefab;
    }

    static Prefabs MakePrefabs()
    {
        var p = new Prefabs();
        chimneyTops.Clear();
        p.pine = TreePrefab("Assets/Prefabs/Nature/Tree_CoastalPine.prefab", PineMesh("SM_Tree_CoastalPine", 4, 2.2f, 1.5f, 2.7f, 1), mBark, mPine);
        p.fir = TreePrefab("Assets/Prefabs/Nature/Tree_TallSpruce.prefab", PineMesh("SM_Tree_TallSpruce", 6, 1.6f, 1.3f, 2.4f, 2), mBark, mPine);
        p.broadleaf = TreePrefab("Assets/Prefabs/Nature/Tree_Broadleaf.prefab", BroadleafMesh("SM_Tree_Broadleaf", 3), mBark, mLeaves);
        p.rockA = MeshPrefab("Assets/Prefabs/Nature/Rock_A.prefab", RockMesh("SM_Rock_A", 21), mRock);
        p.rockB = MeshPrefab("Assets/Prefabs/Nature/Rock_B.prefab", RockMesh("SM_Rock_B", 37), mRock);
        p.rockC = MeshPrefab("Assets/Prefabs/Nature/Rock_C.prefab", RockMesh("SM_Rock_C", 58), mRock);

        Material[] house = { mRed, mRoofSlate, mTrim, mWinLit, mStone, mDoorTeal };
        p.houseA = MeshPrefab("Assets/Prefabs/Buildings/House_Cottage.prefab", HouseMesh("SM_House_Cottage", 5.6f, 7f, 3.0f, 2.3f, false), house);
        p.houseB = MeshPrefab("Assets/Prefabs/Buildings/House_TwoStorey.prefab", HouseMesh("SM_House_TwoStorey", 6.2f, 8.2f, 5.4f, 2.6f, false), house);
        p.houseC = MeshPrefab("Assets/Prefabs/Buildings/House_FishermansHut.prefab", HouseMesh("SM_House_FishermansHut", 4.2f, 5.2f, 2.7f, 1.9f, false), house);
        p.boathouse = MeshPrefab("Assets/Prefabs/Buildings/Boathouse.prefab", HouseMesh("SM_Boathouse", 7f, 9.5f, 3.6f, 2.5f, true), house);

        Material[] boat = { mBoatRed, mBoatInterior, mTrim, mBoatStripeCream, mBoatWhite, mWinDark };
        p.rowboat = MeshPrefab("Assets/Prefabs/Boats/Rowboat.prefab", RowboatMesh(), boat);
        p.fishingBoat = MeshPrefab("Assets/Prefabs/Boats/FishingBoat.prefab", FishingBoatMesh(), boat);
        p.sailboat = MeshPrefab("Assets/Prefabs/Boats/Sailboat.prefab", SailboatMesh(), boat);

        p.barrel = MeshPrefab("Assets/Prefabs/Props/Barrel.prefab", BarrelMesh(), mBarrel, mMetal);
        p.crate = MeshPrefab("Assets/Prefabs/Props/Crate.prefab", CrateMesh(), mCrate);
        p.fishBox = MeshPrefab("Assets/Prefabs/Props/FishBox.prefab", FishBoxMesh(), mCrate, mFish);
        p.rope = MeshPrefab("Assets/Prefabs/Props/RopeCoil.prefab", RopeCoilMesh(), mRope);
        p.lobsterPot = MeshPrefab("Assets/Prefabs/Props/LobsterPot.prefab", LobsterPotMesh(), mDriftwood, mNet);
        p.lantern = LanternMesh();
        p.lanternPost = MeshPrefab("Assets/Prefabs/Props/LanternPost.prefab", LanternPostMesh(), mTrim);
        p.bench = MeshPrefab("Assets/Prefabs/Props/Bench.prefab", BenchMesh(), mWeathered);
        p.fence = MeshPrefab("Assets/Prefabs/Props/FenceSection.prefab", FenceMesh(), mWeathered);
        p.netRack = MeshPrefab("Assets/Prefabs/Props/NetDryingRack.prefab", NetRackMesh(), mTrim, mNet);
        p.fishRack = MeshPrefab("Assets/Prefabs/Props/StockfishRack.prefab", FishRackMesh(), mDriftwood, mFish);
        p.stall = MeshPrefab("Assets/Prefabs/Props/FishStall.prefab", StallMesh(), mWeathered, mAwning);
        p.well = MeshPrefab("Assets/Prefabs/Props/Well.prefab", WellMesh(), mStone, mTrim, mRoofSlate, mWellWater);
        p.cart = MeshPrefab("Assets/Prefabs/Props/HandCart.prefab", CartMesh(), mBarrel, mTrim);
        p.bollard = MeshPrefab("Assets/Prefabs/Props/Bollard.prefab", BollardMesh(), mMetal);
        p.log = MeshPrefab("Assets/Prefabs/Props/DriftwoodLog.prefab", LogMesh(), mDriftwood);
        p.signpost = MeshPrefab("Assets/Prefabs/Props/Signpost.prefab", SignpostMesh(), mWeathered);
        p.embers = MeshPrefab("Assets/Prefabs/Props/CampfireEmbers.prefab", EmberMesh(), mEmbers);
        p.gull = MeshPrefab("Assets/Prefabs/Props/Seagull.prefab", GullMesh(), mGull, mGullTip);
        p.lighthouse = LighthouseMesh();
        p.beam = BeamMesh();
        return p;
    }

    // =====================================================================
    // Terrain
    // =====================================================================
    static Terrain BuildTerrain(Transform parent, Prefabs prefabs)
    {
        padHeights = new float[Sites.Length];
        for (int i = 0; i < Sites.Length; i++) padHeights[i] = BaseHeight(Sites[i].p.x, Sites[i].p.y) + 0.2f;
        squareHeight = BaseHeight(Square.x, Square.y);
        startHeight = BaseHeight(StartPos.x, StartPos.y);
        lighthouseGround = BaseHeight(LighthousePos.x, LighthousePos.y);

        // Textures first: importing assets mid-build can reload an unsaved TerrainData.
        var layers = new[]
        {
            MakeLayer("TL_CoastalGrass", GrassTexture(), 8f),
            MakeLayer("TL_Sand", SandTexture(), 6f),
            MakeLayer("TL_WetSand_Pebbles", WetSandTexture(), 5f),
            MakeLayer("TL_DirtPath", DirtTexture(), 4f),
            MakeLayer("TL_CliffRock", RockTexture(), 9f)
        };
        var grassTexture = GrassBladeTexture();

        var td = new TerrainData();
        td.heightmapResolution = HeightRes;
        td.alphamapResolution = AlphaRes;
        td.size = new Vector3(Size, MaxHeight, Size);

        var heights = new float[HeightRes, HeightRes];
        for (int iz = 0; iz < HeightRes; iz++)
            for (int ix = 0; ix < HeightRes; ix++)
            {
                float x = ix / (float)(HeightRes - 1) * Size;
                float z = iz / (float)(HeightRes - 1) * Size;
                heights[iz, ix] = Mathf.Clamp01(FinalHeight(x, z) / MaxHeight);
            }
        td.SetHeights(0, 0, heights);
        td.terrainLayers = layers;

        var alpha = new float[AlphaRes, AlphaRes, 5];
        for (int iz = 0; iz < AlphaRes; iz++)
            for (int ix = 0; ix < AlphaRes; ix++)
            {
                float nx = ix / (float)(AlphaRes - 1), nz = iz / (float)(AlphaRes - 1);
                float x = nx * Size, z = nz * Size;
                float h = td.GetInterpolatedHeight(nx, nz);
                float steep = td.GetSteepness(nx, nz);
                float n = Fbm(x * 0.06f, z * 0.06f, 3);

                float rock = Mathf.Max(SS(28f, 40f, steep), SS(70f, 90f, h) * 0.7f);
                float wet = 1f - SS(10.1f, 10.9f + n * 0.6f, h);
                float sand = 1f - SS(11.4f, 13.4f + n * 1.5f, h);
                float path = 1f - SS(1.2f, 3.0f, MainPathDist(x, z) + (n - 0.5f) * 1.4f);
                path = Mathf.Max(path, (1f - SS(0.7f, 2.0f, TrailDist(x, z))) * 0.85f);
                Vector2 p = new Vector2(x, z);
                path = Mathf.Max(path, (1f - SS(7f, 11f + n * 3f, Vector2.Distance(p, Square))) * 0.9f);
                path = Mathf.Max(path, (1f - SS(5f, 9f, Vector2.Distance(p, StartPos))) * 0.6f);
                for (int i = 0; i < Sites.Length; i++)
                    path = Mathf.Max(path, (1f - SS(Sites[i].r - 2f, Sites[i].r + 2f, Vector2.Distance(p, Sites[i].p))) * 0.55f);

                float w0 = rock;
                float w1 = Mathf.Max(0f, 1f - w0) * wet;
                float w2 = Mathf.Max(0f, 1f - w0 - w1) * sand;
                float w3 = Mathf.Max(0f, 1f - w0 - w1 - w2) * path;
                float w4 = Mathf.Max(0f, 1f - w0 - w1 - w2 - w3);
                alpha[iz, ix, 0] = w4;
                alpha[iz, ix, 1] = w2;
                alpha[iz, ix, 2] = w1;
                alpha[iz, ix, 3] = w3;
                alpha[iz, ix, 4] = w0;
            }
        td.SetAlphamaps(0, 0, alpha);

        // Trees: windswept pines and spruce on the hills and headlands, a few broadleaf trees in the village
        td.treePrototypes = new[]
        {
            new TreePrototype { prefab = prefabs.pine },
            new TreePrototype { prefab = prefabs.fir },
            new TreePrototype { prefab = prefabs.broadleaf }
        };
        var trees = new List<TreeInstance>();
        var rng = new System.Random(4321);
        const float spacing = 4.6f;
        for (float gz = 2f; gz < Size - 2f; gz += spacing)
            for (float gx = 2f; gx < Size - 2f; gx += spacing)
            {
                float x = gx + ((float)rng.NextDouble() - 0.5f) * spacing * 0.9f;
                float z = gz + ((float)rng.NextDouble() - 0.5f) * spacing * 0.9f;
                float nx = x / Size, nz = z / Size;
                float h = td.GetInterpolatedHeight(nx, nz);
                if (h < 13.5f) continue;                       // no trees on beaches
                if (td.GetSteepness(nx, nz) > 36f) continue;
                Vector2 p = new Vector2(x, z);
                if (MainPathDist(x, z) < 4f || TrailDist(x, z) < 3.2f) continue;
                if (Vector2.Distance(p, Square) < 16f || Vector2.Distance(p, StartPos) < 16f) continue;
                if (Vector2.Distance(p, LighthousePos) < 18f || Vector2.Distance(p, CoveCamp) < 16f) continue;
                bool blocked = false;
                for (int i = 0; i < Sites.Length; i++) if (Vector2.Distance(p, Sites[i].p) < Sites[i].r + 4f) { blocked = true; break; }
                if (blocked) continue;

                bool village = x > 95f && x < 225f && z > 78f && z < 150f;
                // Keep the view from the hilltop down to the harbour open
                bool viewCorridor = x > 125f && x < 205f && z > 50f && z < 90f;
                float keep = 0.55f + (Fbm(x * 0.03f, z * 0.03f, 2) - 0.5f) * 0.7f;
                if (village) keep = 0.1f;
                if (viewCorridor) keep = 0.06f;
                if (z < 40f || x < 40f || x > 282f) keep += 0.25f; // thicker at the world edges
                if (rng.NextDouble() > keep) continue;

                int proto;
                double roll = rng.NextDouble();
                if (village) proto = roll < 0.6 ? 2 : 0;
                else proto = roll < 0.5 ? 0 : (roll < 0.85 ? 1 : 2);

                float hs = 0.75f + (float)rng.NextDouble() * 0.6f;
                trees.Add(new TreeInstance
                {
                    position = new Vector3(nx, 0f, nz),
                    prototypeIndex = proto,
                    heightScale = hs,
                    widthScale = hs * (0.85f + (float)rng.NextDouble() * 0.3f),
                    rotation = (float)rng.NextDouble() * Mathf.PI * 2f,
                    color = Color.Lerp(Color.white, new Color(0.85f, 0.82f, 0.75f), (float)rng.NextDouble()),
                    lightmapColor = Color.white
                });
            }
        td.SetTreeInstances(trees.ToArray(), true);

        // Dune and meadow grass
        var grass = new DetailPrototype
        {
            prototypeTexture = grassTexture,
            renderMode = DetailRenderMode.Grass,
            usePrototypeMesh = false,
            minWidth = 0.5f, maxWidth = 1.0f,
            minHeight = 0.35f, maxHeight = 0.85f,
            noiseSpread = 0.35f,
            healthyColor = new Color(0.62f, 0.62f, 0.36f),
            dryColor = new Color(0.78f, 0.66f, 0.40f)
        };
        td.detailPrototypes = new[] { grass };
        td.SetDetailResolution(DetailRes, 16);
        var detail = new int[DetailRes, DetailRes];
        for (int iz = 0; iz < DetailRes; iz++)
            for (int ix = 0; ix < DetailRes; ix++)
            {
                float x = (ix + 0.5f) / DetailRes * Size, z = (iz + 0.5f) / DetailRes * Size;
                float h = td.GetInterpolatedHeight(x / Size, z / Size);
                if (h < 12.2f) continue;
                if (td.GetSteepness(x / Size, z / Size) > 28f) continue;
                if (MainPathDist(x, z) < 1.8f || TrailDist(x, z) < 1.2f) continue;
                Vector2 p = new Vector2(x, z);
                if (Vector2.Distance(p, Square) < 11f) continue;
                bool onPad = false;
                for (int i = 0; i < Sites.Length; i++) if (Vector2.Distance(p, Sites[i].p) < Sites[i].r) { onPad = true; break; }
                if (onPad) continue;
                float n = Fbm(x * 0.08f, z * 0.08f, 2);
                int v = n > 0.5f ? 4 : (n > 0.4f ? 2 : 1);
                if (h < 13.5f) v = n > 0.5f ? 3 : 0; // tufts of dune grass at the top of the beach
                detail[iz, ix] = v;
            }
        td.SetDetailLayer(0, 0, 0, detail);
        td.wavingGrassStrength = 0.35f;
        td.wavingGrassSpeed = 0.4f;
        td.wavingGrassAmount = 0.35f;
        td.wavingGrassTint = new Color(0.8f, 0.7f, 0.5f);

        AssetDatabase.CreateAsset(td, "Assets/Terrain/TD_FishingVillage.asset");
        var go = Terrain.CreateTerrainGameObject(td);
        go.name = "CoastalTerrain";
        go.transform.SetParent(parent, false);
        var t = go.GetComponent<Terrain>();
        var rp = GraphicsSettings.currentRenderPipeline;
        if (rp != null && rp.defaultTerrainMaterial != null) t.materialTemplate = rp.defaultTerrainMaterial;
        t.treeDistance = 500f;
        t.treeBillboardDistance = 500f;
        t.detailObjectDistance = 100f;
        t.detailObjectDensity = 1f;
        t.heightmapPixelError = 3f;
        t.basemapDistance = 350f;
        t.drawInstanced = true;
        EditorUtility.SetDirty(td);
        return t;
    }

    static TerrainLayer MakeLayer(string name, Texture2D tex, float tile)
    {
        var l = new TerrainLayer { diffuseTexture = tex, tileSize = new Vector2(tile, tile), smoothness = 0f, metallic = 0f };
        AssetDatabase.CreateAsset(l, "Assets/Terrain/" + name + ".terrainlayer");
        return l;
    }

    // =====================================================================
    // Scene helpers
    // =====================================================================
    static float Ground(float x, float z) { return terrain.SampleHeight(new Vector3(x, 0f, z)); }

    static GameObject Group(string name, Transform parent)
    {
        var g = new GameObject(name);
        if (parent != null) g.transform.SetParent(parent, false);
        return g;
    }

    static GameObject Place(GameObject prefab, string name, Transform parent, Vector3 pos, Vector3 euler, float scale = 1f)
    {
        var g = (GameObject)PrefabUtility.InstantiatePrefab(prefab, parent);
        g.name = name;
        g.transform.position = pos;
        g.transform.rotation = Quaternion.Euler(euler);
        g.transform.localScale = Vector3.one * scale;
        return g;
    }

    // Places a prefab on the terrain at (x, z), sunk slightly so it never floats.
    // Settles to the lowest ground under the object's footprint, so nothing hangs in the air on a slope.
    static GameObject PlaceOnGround(GameObject prefab, string name, Transform parent, float x, float z, float yaw, float scale = 1f, float sink = 0.04f)
    {
        var g = Place(prefab, name, parent, new Vector3(x, Ground(x, z) - sink, z), new Vector3(0f, yaw, 0f), scale);
        var r = g.GetComponentInChildren<MeshRenderer>();
        if (r != null)
        {
            var b = r.bounds;
            float minG = Ground(x, z);
            foreach (var c in new[] { new Vector2(b.min.x, b.min.z), new Vector2(b.max.x, b.min.z), new Vector2(b.min.x, b.max.z), new Vector2(b.max.x, b.max.z) })
                minG = Mathf.Min(minG, Ground(Mathf.Lerp(x, c.x, 0.85f), Mathf.Lerp(z, c.y, 0.85f)));
            g.transform.position = new Vector3(x, minG - sink, z);
        }
        return g;
    }

    static void SetMaterials(GameObject g, params Material[] mats)
    {
        g.GetComponentInChildren<MeshRenderer>().sharedMaterials = mats;
    }

    static Light MakeLight(string name, Transform parent, Vector3 pos, LightType type, Color c, float intensity, float range, bool flicker, float flickerAmount = 0.2f)
    {
        var g = new GameObject(name);
        g.transform.SetParent(parent, false);
        g.transform.position = pos;
        var l = g.AddComponent<Light>();
        l.type = type;
        l.color = c;
        l.intensity = intensity;
        l.range = range;
        l.shadows = LightShadows.None;
        if (flicker)
        {
            var f = g.AddComponent<LightFlicker>();
            SetFloat(f, "flickerAmount", flickerAmount);
        }
        return l;
    }

    static void SetFloat(Object o, string prop, float v)
    {
        var so = new SerializedObject(o);
        var p = so.FindProperty(prop);
        if (p == null) { Debug.LogError("Missing property " + prop + " on " + o); return; }
        p.floatValue = v;
        so.ApplyModifiedPropertiesWithoutUndo();
    }

    static void SetVector(Object o, string prop, Vector3 v)
    {
        var so = new SerializedObject(o);
        var p = so.FindProperty(prop);
        if (p == null) { Debug.LogError("Missing property " + prop + " on " + o); return; }
        if (p.propertyType == SerializedPropertyType.Vector2) p.vector2Value = v; else p.vector3Value = v;
        so.ApplyModifiedPropertiesWithoutUndo();
    }

    static void SetBool(Object o, string prop, bool v)
    {
        var so = new SerializedObject(o);
        so.FindProperty(prop).boolValue = v;
        so.ApplyModifiedPropertiesWithoutUndo();
    }

    static BoatBob AddBob(GameObject g, float height, float roll, float pitch, float phase, float speed = 1f)
    {
        var b = g.AddComponent<BoatBob>();
        SetFloat(b, "bobHeight", height);
        SetFloat(b, "rollDegrees", roll);
        SetFloat(b, "pitchDegrees", pitch);
        SetFloat(b, "phaseOffset", phase);
        SetFloat(b, "bobCyclesPerSecond", 0.22f * speed);
        SetFloat(b, "rollCyclesPerSecond", 0.17f * speed);
        SetFloat(b, "pitchCyclesPerSecond", 0.13f * speed);
        return b;
    }

    static GameObject LanternPost(Prefabs p, Transform parent, string name, Vector3 basePos, float yaw, bool withLight, float phase)
    {
        var post = Place(p.lanternPost, name, parent, basePos + Vector3.down * 0.1f, new Vector3(0f, yaw, 0f));
        var pivot = Group("SwingPivot", post.transform);
        pivot.transform.localPosition = new Vector3(0f, 2.72f, 0.68f);
        var sway = pivot.AddComponent<SwayMotion>();
        SetVector(sway, "swayAxis", new Vector3(1f, 0f, 0.3f));
        SetFloat(sway, "swayAngle", 7f);
        SetFloat(sway, "swayCyclesPerSecond", 0.4f);
        SetFloat(sway, "phaseOffset", phase);
        var lantern = Group("Lantern", pivot.transform);
        lantern.AddComponent<MeshFilter>().sharedMesh = p.lantern;
        lantern.AddComponent<MeshRenderer>().sharedMaterials = new[] { mMetal, mLanternGlow };
        if (withLight)
        {
            var l = MakeLight("LanternLight", pivot.transform, Vector3.zero, LightType.Point, new Color(1f, 0.7f, 0.38f), 2.2f, 9f, true, 0.15f);
            l.transform.localPosition = new Vector3(0f, -0.45f, 0f);
        }
        return post;
    }

    // =====================================================================
    // Water and distant islands
    // =====================================================================
    static void BuildWater()
    {
        var water = Group("Water", null).transform;
        var mesh = new Mesh { name = "SM_SeaPlane" };
        const float half = 1500f;
        mesh.SetVertices(new List<Vector3> { new Vector3(-half, 0f, -half), new Vector3(half, 0f, -half), new Vector3(half, 0f, half), new Vector3(-half, 0f, half) });
        mesh.SetUVs(0, new List<Vector2> { new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(0f, 1f) });
        mesh.SetTriangles(new[] { 0, 2, 1, 0, 3, 2 }, 0);
        mesh.RecalculateNormals(); mesh.RecalculateTangents(); mesh.RecalculateBounds();
        AssetDatabase.CreateAsset(mesh, "Assets/Meshes/Props/SM_SeaPlane.asset");

        var sea = Group("Sea", water);
        sea.transform.position = new Vector3(160f, WaterLevel, 160f);
        sea.AddComponent<MeshFilter>().sharedMesh = mesh;
        var mr = sea.AddComponent<MeshRenderer>();
        mr.sharedMaterial = mSea;
        mr.shadowCastingMode = ShadowCastingMode.Off;
        var scroll = sea.AddComponent<WaterScroll>();
        SetVector(scroll, "scrollSpeed", new Vector2(0.0035f, 0.002f));
    }

    // =====================================================================
    // Buildings
    // =====================================================================
    static Transform houseRoot;
    static readonly List<GameObject> houses = new List<GameObject>();

    static void BuildBuildings(Prefabs p)
    {
        var buildings = Group("Buildings", null).transform;
        buildingsRoot = buildings;
        houseRoot = Group("Houses", buildings).transform;
        houses.Clear();
        // prefab, name, walls, roof, door, lit windows
        object[][] defs =
        {
            new object[] { p.houseA, "House_RedCottage", mRed, mRoofSlate, mDoorTeal, true },
            new object[] { p.houseB, "House_MustardTwoStorey", mMustard, mRoofSlate, mDoorRed, true },
            new object[] { p.houseA, "House_BlueCottage", mBlue, mRoofTar, mDoorRed, false },
            new object[] { p.houseA, "House_Whitewashed", mWhite, mRoofSlate, mDoorTeal, true },
            new object[] { p.houseC, "Hut_NetMender", mWeathered, mRoofTar, mDoorTeal, false },
            new object[] { p.houseB, "House_RedTwoStorey", mRed, mRoofTar, mDoorTeal, true },
            new object[] { p.boathouse, "Boathouse", mWeathered, mRoofTar, mDoorRed, false },
            new object[] { p.houseC, "Hut_Mustard", mMustard, mRoofSlate, mDoorTeal, true },
            new object[] { p.houseC, "Cottage_LighthouseKeeper", mWhite, mRoofSlate, mDoorRed, true },
            new object[] { p.houseC, "Hut_Cove", mWeathered, mRoofTar, mDoorRed, false },
        };
        for (int i = 0; i < Sites.Length; i++)
        {
            var d = defs[i];
            var s = Sites[i];
            var go = Place((GameObject)d[0], (string)d[1], houseRoot, new Vector3(s.p.x, padHeights[i] - 0.25f, s.p.y), new Vector3(0f, s.yaw, 0f));
            SetMaterials(go, (Material)d[2], (Material)d[3], mTrim, (bool)d[5] ? mWinLit : mWinDark, mStone, (Material)d[4]);
            houses.Add(go);
        }
        // Make sure each house sits on its pad: drop it to the lowest ground under its footprint, minus a little
        foreach (var h in houses)
        {
            var b = h.GetComponent<MeshRenderer>().bounds;
            float minG = float.MaxValue;
            for (int ix = -1; ix <= 1; ix++)
                for (int iz = -1; iz <= 1; iz++)
                    minG = Mathf.Min(minG, Ground(h.transform.position.x + ix * b.extents.x * 0.9f, h.transform.position.z + iz * b.extents.z * 0.9f));
            var pos = h.transform.position;
            pos.y = Mathf.Min(pos.y, minG) - 0.15f;
            h.transform.position = pos;
        }

        // Warm light spilling from the windows of the lit houses
        var lights = Group("WindowLights", buildings).transform;
        int[] lit = { 0, 1, 5 };
        foreach (int i in lit)
        {
            var h = houses[i].transform;
            var b = houses[i].GetComponent<MeshFilter>().sharedMesh.bounds;
            Vector3 pos = h.TransformPoint(new Vector3(b.extents.x * 0.35f, 2.0f, b.max.z + 1.6f));
            MakeLight("WindowGlow_" + houses[i].name, lights, pos, LightType.Point, new Color(1f, 0.68f, 0.36f), 1.6f, 7f, false);
        }
    }

    static Vector3 lampPos;

    static void BuildLighthouse(Prefabs p)
    {
        var root = Group("Lighthouse", buildingsRoot).transform;
        float g = Ground(LighthousePos.x, LighthousePos.y);
        root.position = new Vector3(LighthousePos.x, g, LighthousePos.y);
        root.rotation = Quaternion.Euler(0f, 200f, 0f);
        var tower = Group("Tower", root);
        tower.transform.localPosition = Vector3.zero;
        tower.transform.localRotation = Quaternion.identity;
        tower.AddComponent<MeshFilter>().sharedMesh = p.lighthouse;
        tower.AddComponent<MeshRenderer>().sharedMaterials = new[] { mLhWhite, mLhRed, mStone, mLhLamp, mMetal };

        lampPos = root.position + Vector3.up * 19.7f;
        var pivot = Group("BeamPivot", root);
        pivot.transform.position = lampPos;
        var rot = pivot.AddComponent<Rotator>();
        SetVector(rot, "degreesPerSecond", new Vector3(0f, 32f, 0f));
        foreach (float yaw in new[] { 0f, 180f })
        {
            var beam = Group(yaw == 0f ? "Beam_Front" : "Beam_Back", pivot.transform);
            beam.transform.localPosition = Vector3.zero;
            beam.transform.localRotation = Quaternion.Euler(4f, yaw, 0f);
            beam.AddComponent<MeshFilter>().sharedMesh = p.beam;
            var mr = beam.AddComponent<MeshRenderer>();
            mr.sharedMaterial = mBeam;
            mr.shadowCastingMode = ShadowCastingMode.Off;
            mr.receiveShadows = false;
        }
        var spot = MakeLight("BeamSpotLight", pivot.transform, lampPos, LightType.Spot, new Color(1f, 0.88f, 0.6f), 40f, 140f, false);
        spot.transform.localRotation = Quaternion.Euler(4f, 0f, 0f);
        spot.spotAngle = 14f;
        spot.innerSpotAngle = 6f;
        MakeLight("LampRoomGlow", root, lampPos, LightType.Point, new Color(1f, 0.85f, 0.6f), 5f, 22f, false);

        // Bench and fence at the headland viewpoint
        var props = Group("HeadlandProps", root.parent);
        float bx = 247f, bz = 210f;
        PlaceOnGround(p.bench, "Bench_HeadlandView", props.transform, bx, bz, -75f);
        var edge = new List<Vector2>();
        for (float x = 246f; x <= 276f; x += 2.5f) edge.Add(new Vector2(x, ShoreZ(x) - 11f));
        for (int i = 1; i < edge.Count; i++)
        {
            Vector2 a = edge[i - 1], c = edge[i], mid = (a + c) * 0.5f, dir = (c - a).normalized;
            float yaw = Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg - 90f;
            float g0 = Ground(a.x, a.y), g1 = Ground(c.x, c.y);
            var f = Place(p.fence, "Fence_Clifftop_" + i, props.transform, new Vector3(mid.x, Ground(mid.x, mid.y) - 0.1f, mid.y), Vector3.zero);
            f.transform.rotation = Quaternion.Euler(0f, yaw, Mathf.Atan2(g1 - g0, (c - a).magnitude) * Mathf.Rad2Deg);
            f.transform.localScale = new Vector3((c - a).magnitude / 2.5f, 1f, 1f);
        }
        PlaceOnGround(p.barrel, "Barrel_LampOil_1", props.transform, LighthousePos.x - 3.8f, LighthousePos.y - 2.5f, 20f);
        PlaceOnGround(p.barrel, "Barrel_LampOil_2", props.transform, LighthousePos.x - 4.5f, LighthousePos.y - 1.6f, 70f);
    }

