    static void FenceAlong(Prefabs p, Transform parent, string name, Vector2[] pts, float from, float to, float offset)
    {
        var samples = SamplePath(pts);
        int a = Mathf.FloorToInt(samples.Count * from), b = Mathf.FloorToInt(samples.Count * to);
        float acc = 0f;
        int n = 0;
        for (int i = a + 1; i < b; i++)
        {
            acc += Vector2.Distance(samples[i], samples[i - 1]);
            if (acc < 2.6f) continue;
            acc = 0f;
            Vector2 dir = (samples[i] - samples[i - 1]).normalized;
            Vector2 side = new Vector2(dir.y, -dir.x) * offset;
            Vector2 pos = samples[i] - dir * 1.3f + side;
            float yaw = Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg - 90f;
            var f = Place(p.fence, name + "_" + (++n), parent, new Vector3(pos.x, Ground(pos.x, pos.y) - 0.1f, pos.y), new Vector3(0f, yaw, 0f));
            // tilt to follow the slope
            float g0 = Ground(pos.x - dir.x * 1.25f, pos.y - dir.y * 1.25f), g1 = Ground(pos.x + dir.x * 1.25f, pos.y + dir.y * 1.25f);
            f.transform.rotation = Quaternion.Euler(0f, yaw, Mathf.Atan2(g1 - g0, 2.5f) * Mathf.Rad2Deg);
        }
    }

    // =====================================================================
    // The cove: upturned boat, campfire, driftwood
    // =====================================================================
    static Vector3 campfirePos;

    static void BuildCove(Prefabs p)
    {
        var cove = Group("Cove", propsRoot).transform;
        float cx = CoveCamp.x, cz = CoveCamp.y;
        campfirePos = new Vector3(cx, Ground(cx, cz), cz);

        var fire = Group("Campfire", cove).transform;
        fire.position = campfirePos;
        Place(p.embers, "Embers", fire, campfirePos + Vector3.down * 0.05f, Vector3.zero);
        for (int i = 0; i < 4; i++)
        {
            var lg = Place(p.log, "FireLog_" + (i + 1), fire, campfirePos + Vector3.up * 0.1f, new Vector3(0f, i * 45f, 18f), 0.42f);
            lg.transform.position += Quaternion.Euler(0f, i * 45f, 0f) * Vector3.right * 0.05f;
        }
        for (int i = 0; i < 9; i++)
        {
            float a = i * Mathf.PI * 2f / 9f;
            float x = cx + Mathf.Cos(a) * 0.85f, z = cz + Mathf.Sin(a) * 0.85f;
            Place(i % 2 == 0 ? p.rockA : p.rockB, "FireRingStone_" + (i + 1), fire, new Vector3(x, Ground(x, z) + 0.02f, z), new Vector3(0f, i * 40f, 0f), 0.22f);
        }
        PlaceOnGround(p.log, "LogSeat_1", cove, cx + 2.2f, cz - 0.6f, 75f, 1f, -0.12f);
        PlaceOnGround(p.log, "LogSeat_2", cove, cx - 1.6f, cz - 2.0f, 30f, 1f, -0.12f);

        // Upturned rowboat on trestles, mid-repair
        float bx = cx + 4.5f, bz = cz - 6f;
        float g = Ground(bx, bz);
        foreach (float off in new[] { -1.2f, 1.2f })
        {
            var tr = PlaceOnGround(p.bench, "Trestle_" + (off < 0 ? "A" : "B"), cove, bx + off * Mathf.Sin(20f * Mathf.Deg2Rad), bz + off * Mathf.Cos(20f * Mathf.Deg2Rad), 110f, 1f, 0.05f);
        }
        var boat = Place(p.rowboat, "Boat_Rowboat_UnderRepair", cove, new Vector3(bx, g + 1.08f, bz), new Vector3(0f, 20f, 180f));
        SetMaterials(boat, mBoatBlue, mBoatInterior, mTrim, mBoatWhite, mBoatWhite, mWinDark);
        PlaceOnGround(p.barrel, "Barrel_Tar", cove, bx + 2f, bz + 1.4f, 0f);
        PlaceOnGround(p.crate, "Crate_Tools", cove, bx - 1.8f, bz + 1.6f, 15f);

        var rng = new System.Random(222);
        for (int i = 0; i < 5; i++)
        {
            float x = cx - 18f + (float)rng.NextDouble() * 34f, z = cz + 2f + (float)rng.NextDouble() * 4f;
            if (Ground(x, z) < WaterLevel + 0.15f) continue;
            PlaceOnGround(p.log, "Driftwood_" + (i + 1), cove, x, z, (float)rng.NextDouble() * 180f, 0.6f + (float)rng.NextDouble() * 0.6f, 0.08f);
        }
        PlaceOnGround(p.netRack, "NetDryingRack_Cove", cove, 62f, 158f, 40f, 1f, 0.2f);
    }

