    // =====================================================================
    // Rocks and distant islands
    // =====================================================================
    static void BuildNature(Prefabs p)
    {
        var nature = Group("Nature", null).transform;
        var rocks = Group("ShoreRocks", nature).transform;
        var rng = new System.Random(55);
        GameObject[] rockPrefabs = { p.rockA, p.rockB, p.rockC };
        int n = 0;
        // Boulders scattered along the shoreline, kept clear of the harbour
        for (float x = 20f; x < 300f; x += 3.2f)
        {
            if (x > 138f && x < 200f) continue;
            if (rng.NextDouble() > 0.5) continue;
            float z = ShoreZ(x) + ((float)rng.NextDouble() - 0.6f) * 6f;
            if (Vector2.Distance(new Vector2(x, z), CoveCamp) < 9f) continue;
            float s = 0.6f + (float)rng.NextDouble() * 1.8f;
            if (Gauss(x, 262f, 28f) > 0.3f || Gauss(x, 25f, 25f) > 0.3f) s *= 1.8f; // bigger rocks under the cliffs
            float g = Ground(x, z);
            for (int k = 0; k < 8; k++) g = Mathf.Min(g, Ground(x + Mathf.Cos(k * 0.785f) * s, z + Mathf.Sin(k * 0.785f) * s));
            Place(rockPrefabs[n % 3], "ShoreRock_" + (++n), rocks, new Vector3(x, Mathf.Max(g, WaterLevel - 1.2f) - s * 0.2f, z),
                new Vector3((float)rng.NextDouble() * 20f, (float)rng.NextDouble() * 360f, (float)rng.NextDouble() * 20f), s);
        }
        // Rocks breaking the surface out in the bay
        Vector2[] seaRocks = { new Vector2(118f, 198f), new Vector2(121f, 201f), new Vector2(228f, 260f), new Vector2(90f, 230f) };
        foreach (var s in seaRocks)
            Place(rockPrefabs[n % 3], "SeaRock_" + (++n), rocks, new Vector3(s.x, WaterLevel - 0.6f, s.y), new Vector3(0f, n * 47f, 0f), 2.2f + (n % 3) * 0.8f);

        var islands = Group("DistantIslands", nature).transform;
        Vector3[] isl = { new Vector3(40f, WaterLevel - 6f, 560f), new Vector3(330f, WaterLevel - 8f, 640f), new Vector3(-180f, WaterLevel - 6f, 470f), new Vector3(150f, WaterLevel - 5f, 760f) };
        Vector3[] islScale = { new Vector3(70f, 26f, 40f), new Vector3(110f, 34f, 55f), new Vector3(60f, 20f, 40f), new Vector3(90f, 18f, 50f) };
        for (int i = 0; i < isl.Length; i++)
        {
            var g = Place(rockPrefabs[i % 3], "Island_" + (i + 1), islands, isl[i], new Vector3(0f, i * 70f, 0f));
            g.transform.localScale = islScale[i];
            g.GetComponent<MeshRenderer>().sharedMaterial = mIslandRock;
            g.GetComponent<MeshRenderer>().shadowCastingMode = ShadowCastingMode.Off;
        }
    }

    // =====================================================================
    // Effects: campfire, chimney smoke, seagulls
    // =====================================================================
    static void BuildEffects(Prefabs p)
    {
        var fx = Group("Effects", null).transform;
        Flames(fx, "CampfireFlames", campfirePos + Vector3.up * 0.15f);
        Smoke(fx, "CampfireSmoke", campfirePos + Vector3.up * 1.2f, 3f, 0.9f);
        foreach (int i in new[] { 1, 5, 8 })
        {
            var h = houses[i].transform;
            var mesh = houses[i].GetComponent<MeshFilter>().sharedMesh;
            Vector3 local;
            if (!chimneyTops.TryGetValue(mesh, out local)) continue;
            Smoke(fx, "ChimneySmoke_" + houses[i].name, h.TransformPoint(local + Vector3.up * 0.3f), 2.2f, 0.7f);
        }
        var campLight = MakeLight("CampfireLight", pointLightsRoot, campfirePos + Vector3.up * 0.8f, LightType.Point, new Color(1f, 0.55f, 0.22f), 3.5f, 12f, true, 0.35f);
        SetFloat(campLight.GetComponent<LightFlicker>(), "flickerSpeed", 6f);

        var gulls = Group("Seagulls", fx).transform;
        GullFlock(p, gulls, "Flock_Harbour", new Vector3(162f, 26f, 168f), 3, 15f);
        GullFlock(p, gulls, "Flock_Lighthouse", new Vector3(262f, 44f, 222f), 2, 11f);
        GullFlock(p, gulls, "Flock_Boat", new Vector3(206f, 19f, 214f), 2, 7f);
    }

    static void GullFlock(Prefabs p, Transform parent, string name, Vector3 centre, int count, float radius)
    {
        var flock = Group(name, parent);
        flock.transform.position = centre;
        for (int i = 0; i < count; i++)
        {
            var g = Place(p.gull, "Seagull_" + (i + 1), flock.transform, centre, Vector3.zero);
            var c = g.AddComponent<GullCircle>();
            SetFloat(c, "radius", radius * (0.8f + 0.25f * i));
            SetFloat(c, "startAngle", i * 137f);
            SetFloat(c, "degreesPerSecond", 16f + i * 4f);
            SetFloat(c, "heightWave", 1.2f + i * 0.5f);
            SetBool(c, "clockwise", i % 2 == 1);
            g.transform.localPosition = new Vector3(Mathf.Cos(i * 137f * Mathf.Deg2Rad), 0f, Mathf.Sin(i * 137f * Mathf.Deg2Rad)) * radius;
        }
    }

    static void Flames(Transform parent, string name, Vector3 pos)
    {
        var go = Group(name, parent);
        go.transform.position = pos;
        var ps = go.AddComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = true; main.prewarm = true;
        main.startLifetime = new ParticleSystem.MinMaxCurve(0.5f, 0.9f);
        main.startSpeed = new ParticleSystem.MinMaxCurve(0.6f, 1.3f);
        main.startSize = new ParticleSystem.MinMaxCurve(0.35f, 0.65f);
        main.startColor = new ParticleSystem.MinMaxGradient(new Color(1f, 0.75f, 0.3f), new Color(1f, 0.45f, 0.15f));
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.maxParticles = 80;
        var em = ps.emission; em.rateOverTime = 40f;
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Cone; shape.angle = 10f; shape.radius = 0.25f;
        shape.rotation = new Vector3(-90f, 0f, 0f);
        var size = ps.sizeOverLifetime; size.enabled = true; size.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 1f, 1f, 0.1f));
        var col = ps.colorOverLifetime; col.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(new Color(1f, 0.4f, 0.2f), 1f) },
                     new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(1f, 0.15f), new GradientAlphaKey(0f, 1f) });
        col.color = new ParticleSystem.MinMaxGradient(grad);
        var r = go.GetComponent<ParticleSystemRenderer>();
        r.sharedMaterial = mFlame;
        r.shadowCastingMode = ShadowCastingMode.Off; r.receiveShadows = false;
        ps.Play();
    }

    static void Smoke(Transform parent, string name, Vector3 pos, float lifetime, float size)
    {
        var go = Group(name, parent);
        go.transform.position = pos;
        var ps = go.AddComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = true; main.prewarm = true;
        main.startLifetime = new ParticleSystem.MinMaxCurve(lifetime * 0.8f, lifetime * 1.3f);
        main.startSpeed = new ParticleSystem.MinMaxCurve(0.5f, 0.9f);
        main.startSize = new ParticleSystem.MinMaxCurve(size * 0.6f, size);
        main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.maxParticles = 60;
        var em = ps.emission; em.rateOverTime = 6f;
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Cone; shape.angle = 8f; shape.radius = 0.15f;
        shape.rotation = new Vector3(-90f, 0f, 0f);
        var vel = ps.velocityOverLifetime; vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
        vel.x = new ParticleSystem.MinMaxCurve(0.4f, 0.4f); vel.y = new ParticleSystem.MinMaxCurve(0.1f, 0.1f); vel.z = new ParticleSystem.MinMaxCurve(-0.25f, -0.25f); // drift with the sea breeze
        var sz = ps.sizeOverLifetime; sz.enabled = true; sz.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0.6f, 1f, 2.6f));
        var col = ps.colorOverLifetime; col.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                     new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(0.8f, 0.15f), new GradientAlphaKey(0f, 1f) });
        col.color = new ParticleSystem.MinMaxGradient(grad);
        var r = go.GetComponent<ParticleSystemRenderer>();
        r.sharedMaterial = mSmoke;
        r.shadowCastingMode = ShadowCastingMode.Off; r.receiveShadows = false;
        ps.Play();
    }

    // =====================================================================
    // Lighting, sky, fog, post-processing
    // =====================================================================
    static GameObject BuildLighting()
    {
        var lighting = Group("Lighting", null);

        // Low sun in the west-north-west, just above the sea horizon
        Vector3 towardSun = new Vector3(-0.88f, 0.125f, 0.44f).normalized;
        var sunGo = Group("Sun_LowWesterly", lighting.transform);
        sunGo.transform.rotation = Quaternion.LookRotation(-towardSun, Vector3.up);
        sun = sunGo.AddComponent<Light>();
        sun.type = LightType.Directional;
        sun.color = new Color(1f, 0.64f, 0.38f);
        sun.intensity = 1.9f;
        sun.shadows = LightShadows.Soft;
        sun.shadowStrength = 0.82f;
        sun.shadowBias = 0.08f;
        sun.shadowNormalBias = 0.5f;

        var skyShader = Shader.Find("FishingVillage/SunsetSkybox");
        if (skyShader != null)
        {
            mSky = new Material(skyShader) { name = "M_Sky_Sunset" };
            mSky.SetVector("_SunDirection", towardSun);
            mSky.SetFloat("_SunSize", 0.022f);
            mSky.SetFloat("_HaloTightness", 22f);
            mSky.SetFloat("_HaloStrength", 0.7f);
        }
        else
        {
            Debug.LogWarning("SunsetSkybox shader not found, using procedural sky");
            mSky = new Material(Shader.Find("Skybox/Procedural")) { name = "M_Sky_Sunset" };
        }
        AssetDatabase.CreateAsset(mSky, "Assets/Materials/Sky/M_Sky_Sunset.mat");

        Color fogColour = new Color(0.86f, 0.58f, 0.46f);
        RenderSettings.skybox = mSky;
        RenderSettings.sun = sun;
        RenderSettings.ambientMode = AmbientMode.Trilight;
        RenderSettings.ambientSkyColor = new Color(0.50f, 0.44f, 0.58f);
        RenderSettings.ambientEquatorColor = new Color(0.62f, 0.44f, 0.38f);
        RenderSettings.ambientGroundColor = new Color(0.22f, 0.17f, 0.16f);
        RenderSettings.fog = true;
        RenderSettings.fogMode = FogMode.Exponential;
        RenderSettings.fogColor = fogColour;
        RenderSettings.fogDensity = 0.0042f;
        RenderSettings.defaultReflectionMode = DefaultReflectionMode.Skybox;
        RenderSettings.reflectionIntensity = 1f;

        var urp = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
        if (urp != null)
        {
            urp.shadowDistance = 260f;
            urp.shadowCascadeCount = 4;
            EditorUtility.SetDirty(urp);
        }

        pointLightsRoot = Group("PointLights", lighting.transform).transform;

        var volumeGo = Group("PostProcessing_Volume", lighting.transform);
        var volume = volumeGo.AddComponent<Volume>();
        volume.isGlobal = true;
        var profile = ScriptableObject.CreateInstance<VolumeProfile>();
        AssetDatabase.CreateAsset(profile, "Assets/Settings/PP_FishingVillage.asset");
        var bloom = profile.Add<Bloom>(true);
        bloom.threshold.Override(0.95f);
        bloom.intensity.Override(0.9f);
        bloom.scatter.Override(0.7f);
        bloom.tint.Override(new Color(1f, 0.86f, 0.72f));
        var tone = profile.Add<Tonemapping>(true);
        tone.mode.Override(TonemappingMode.ACES);
        var vig = profile.Add<Vignette>(true);
        vig.intensity.Override(0.26f);
        vig.smoothness.Override(0.45f);
        var col = profile.Add<ColorAdjustments>(true);
        col.postExposure.Override(0.35f);
        col.contrast.Override(12f);
        col.saturation.Override(10f);
        var wb = profile.Add<WhiteBalance>(true);
        wb.temperature.Override(8f);
        foreach (var c in profile.components) AssetDatabase.AddObjectToAsset(c, profile);
        EditorUtility.SetDirty(profile);
        volume.sharedProfile = profile;
        return lighting;
    }

    // Bakes only the environment (sky reflections and ambient probe), no lightmaps, so the glossy sea mirrors the sunset.
    static void BakeEnvironmentLighting()
    {
        var ls = new LightingSettings { name = "LS_FishingVillage", bakedGI = false, realtimeGI = false };
        AssetDatabase.CreateAsset(ls, "Assets/Settings/LS_FishingVillage.lighting");
        Lightmapping.lightingSettings = ls;
        Lightmapping.Bake();
    }

    // =====================================================================
    // Player camera and viewpoints
    // =====================================================================
    static void BuildPlayerAndViewpoints()
    {
        var vps = Group("Viewpoints", null).transform;
        var vp1 = MakeViewpoint(vps, "Viewpoint1_HillsideArrival", new Vector3(StartPos.x, Ground(StartPos.x, StartPos.y) + 2.4f, StartPos.y), new Vector3(178f, 14f, 160f));
        var vp2 = MakeViewpoint(vps, "Viewpoint2_PierEnd", new Vector3(154.5f, 13.3f, 186.5f), new Vector3(168f, 20f, 112f));
        float hx = 246f, hz = 206f;
        var vp3 = MakeViewpoint(vps, "Viewpoint3_LighthouseHeadland", new Vector3(hx, Ground(hx, hz) + 2.2f, hz), new Vector3(150f, 14f, 184f));

        var player = Group("Player", null).transform;
        var camGo = new GameObject("Main Camera");
        camGo.tag = "MainCamera";
        camGo.transform.SetParent(player, false);
        camGo.transform.SetPositionAndRotation(vp1.position, vp1.rotation);
        var cam = camGo.AddComponent<Camera>();
        cam.fieldOfView = 60f;
        cam.nearClipPlane = 0.2f;
        cam.farClipPlane = 1500f;
        cam.clearFlags = CameraClearFlags.Skybox;
        camGo.AddComponent<AudioListener>();
        var data = camGo.AddComponent<UniversalAdditionalCameraData>();
        data.renderPostProcessing = true;
        data.antialiasing = AntialiasingMode.SubpixelMorphologicalAntiAliasing;

        var explorer = camGo.AddComponent<ExplorerCamera>();
        var so = new SerializedObject(explorer);
        so.FindProperty("terrain").objectReferenceValue = terrain;
        var arr = so.FindProperty("viewpoints");
        arr.arraySize = 3;
        arr.GetArrayElementAtIndex(0).objectReferenceValue = vp1;
        arr.GetArrayElementAtIndex(1).objectReferenceValue = vp2;
        arr.GetArrayElementAtIndex(2).objectReferenceValue = vp3;
        so.FindProperty("waterLevel").floatValue = WaterLevel;
        so.FindProperty("boundsCentre").vector3Value = new Vector3(160f, 0f, 150f);
        so.FindProperty("boundsRadius").floatValue = 118f;
        so.ApplyModifiedPropertiesWithoutUndo();
    }

    static Transform MakeViewpoint(Transform parent, string name, Vector3 pos, Vector3 lookAt)
    {
        var g = Group(name, parent);
        g.transform.position = pos;
        g.transform.rotation = Quaternion.LookRotation(lookAt - pos, Vector3.up);
        return g.transform;
    }
}
